/* --- src/systems/ZoneWild.js --- */
/* ============================================================================
   BLACKOUT OPS — The wild Zone
   · Animals: rabbits, pheasants, deer, boar, mountain goats, feral cattle,
     wolf packs and bears roam their biomes. Hunt them for raw meat, hide,
     feathers, bone, fat, wool and antlers. Prey flees from noise and from you;
     boar and cattle fight back; wolves hunt at night; bears guard their ground.
   · Food: raw meat fills a little (and may make you sick); cooked food
     restores three times as much. Cooking-station meals are bigger still.
   · Stations: fire camp, cooking station, tanning rack, smokehouse visuals.
   · Vehicles: models for all twenty, parked vehicles to claim around the Zone,
     build-only vehicles, and a ride key.
   · World weapons: region-themed weapon caches in fixed places.
   · Box of Wonders: the sandbox master box (every item, weapon and vehicle).
============================================================================ */
(function (BO) {
    'use strict';

    const SPECIES = {
        rabbit: { name: 'Rabbit', hp: 18, speed: 5.4, size: 0.34, color: 0xa89076, temper: 'flee', scare: 14, xp: 6, drops: { raw_rabbit: [1, 1], hide: [0, 1] }, biomes: { meadow: 4, forest: 2, town: 1, wetland: 1 } },
        fowl: { name: 'Pheasant', hp: 14, speed: 4.4, size: 0.3, color: 0x8a5a30, temper: 'flee', scare: 12, xp: 5, drops: { raw_fowl: [1, 1], feather: [2, 4], egg: [0, 1] }, biomes: { meadow: 3, forest: 2, wetland: 2, town: 2 } },
        deer: { name: 'Deer', hp: 70, speed: 6.2, size: 1.0, color: 0x9a6a40, temper: 'flee', scare: 24, xp: 14, drops: { raw_venison: [2, 3], hide: [1, 2], antler: [0, 1], bone: [1, 1] }, biomes: { forest: 4, meadow: 3, alpine: 1 } },
        boar: { name: 'Wild boar', hp: 110, speed: 5.0, size: 0.75, color: 0x4a3a30, temper: 'defend', scare: 10, dmg: 14, xp: 20, drops: { raw_pork: [2, 4], hide: [1, 1], fat: [1, 2] }, biomes: { forest: 4, meadow: 1, wetland: 2 } },
        goat: { name: 'Mountain goat', hp: 60, speed: 4.8, size: 0.7, color: 0xd8d2c4, temper: 'flee', scare: 16, xp: 12, drops: { raw_mutton: [2, 3], wool: [2, 3], bone: [1, 1] }, biomes: { alpine: 5, ash: 1 } },
        cow: { name: 'Feral cattle', hp: 140, speed: 3.4, size: 1.15, color: 0x6a4a3a, temper: 'defend', scare: 8, dmg: 12, xp: 16, drops: { raw_beef: [3, 5], hide: [2, 3], fat: [1, 1], bone: [2, 2] }, biomes: { meadow: 3, wetland: 1, town: 0.5 } },
        wolf: { name: 'Grey wolf', hp: 80, speed: 6.6, size: 0.75, color: 0x6c6c70, temper: 'hunt', scare: 0, dmg: 11, xp: 22, pack: [2, 4], night: 2.5, drops: { raw_wolf: [1, 2], hide: [1, 1], bone: [1, 2] }, biomes: { forest: 2, alpine: 3, meadow: 0.5 } },
        bear: { name: 'Brown bear', hp: 320, speed: 5.6, size: 1.5, color: 0x4a3222, temper: 'territorial', scare: 0, dmg: 26, xp: 60, drops: { raw_bear: [4, 6], hide: [3, 4], fat: [2, 3], bone: [3, 3] }, biomes: { forest: 1, alpine: 1.5 } }
    };

    // f food, h health, w water; raw: may cause food poisoning. Cooked = 3× raw.
    const FOOD = {
        raw_venison: { f: 10, h: 2, raw: 1 }, cooked_venison: { f: 30, h: 6 },
        raw_pork: { f: 10, h: 2, raw: 1 }, cooked_pork: { f: 30, h: 6 },
        raw_rabbit: { f: 7, h: 1, raw: 1 }, cooked_rabbit: { f: 21, h: 3 },
        raw_fowl: { f: 7, h: 1, raw: 1 }, cooked_fowl: { f: 21, h: 3 },
        raw_mutton: { f: 9, h: 2, raw: 1 }, cooked_mutton: { f: 27, h: 6 },
        raw_bear: { f: 13, h: 3, raw: 1 }, cooked_bear: { f: 39, h: 9 },
        raw_wolf: { f: 6, h: 1, raw: 1 }, cooked_wolf: { f: 18, h: 3 },
        raw_beef: { f: 12, h: 3, raw: 1 }, cooked_beef: { f: 36, h: 9 },
        raw_fish: { f: 8, h: 2, raw: 1 }, cooked_fish: { f: 24, h: 6 },
        egg: { f: 4, h: 1, raw: 1 }, fried_egg: { f: 12, h: 3 },
        mushroom: { f: 3, h: 1, raw: 1 }, roast_mushroom: { f: 9, h: 3 },
        berries: { f: 5, h: 1, w: 3 }, honey: { f: 8, h: 4 }, jerky: { f: 18, h: 2 },
        hunter_stew: { f: 70, h: 30, w: 35, warm: 1 }, meat_pie: { f: 45, h: 15 }, omelette: { f: 35, h: 20, stam: 1 },
        mushroom_soup: { f: 30, h: 10, w: 30, warm: 1 }, berry_pie: { f: 40, h: 10, comp: 30 }, honey_ham: { f: 55, h: 20, regen: 60 },
        survivor_feast: { f: 100, h: 50, w: 50, regen: 120, comp: 50 }, golden_ration: { f: 20, h: 60, regen: 30 }
    };

    const WORLD_WEAPONS = {
        crash: ['double_barrel', 'm1911', 'machete_jungle'], relay: ['kar98k_irons', 'r870', 'tomahawk_axe'],
        hollow: ['r870', 'glock18_auto', 'mp5', 'm1014_cod4', 'riot_baton', 'python_magnum'], pine: ['kar98k_irons', 'm40a3_cod4', 'model_1887_mw2', 'machete_jungle'],
        kessel: ['mp7_navy', 'ump45', 'aks74u', 'mac10_uzi', 'crowbar_heavy', 'm4a1'], spillway: ['famas_f1', 'galil_ar', 'spas12_tac', 'r700_cod4'],
        frost: ['dragunov_svd', 'intervention', 'mk14', 'sledge_hammer'], cinder: ['rpd', 'm249', 'aa12', 'saiga12_k', 'chainsaw_ripper'],
        campus: ['raygun', 'tesla_wunder', 'cryo_sceptre', 'vector_kriss', 'xm8_storm'], crater: ['raygun_mk2', 'void_singularity', 'solar_lance', 'barrett_50cal', 'reaper_scythe']
    };

    const rnd = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
    const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

    /* ================================================================ animals */
    class Animal {
        constructor(id, kind, x, y, z) {
            this.animal = true;
            this.id = id;
            this.kind = kind;
            this.spec = SPECIES[kind];
            this.maxHp = this.spec.hp;
            this.hp = this.maxHp;
            this.alive = true;
            this.team = 2;
            this.pos = new THREE.Vector3(x, y, z);
            this.yaw = Math.random() * Math.PI * 2;
            this.state = 'wander';
            this.goal = null;
            this.timer = 0;
            this.attackCd = 0;
            this.phase = Math.random() * 6;
            this.deathTimer = 0;
            this.build();
        }

        build() {
            const s = this.spec.size;
            const k = this.kind;
            const root = new THREE.Group();
            const mat = (c) => new THREE.MeshStandardMaterial({ color: new THREE.Color(c).convertSRGBToLinear(), roughness: 0.9 });
            const body = this.spec.color;
            const dark = new THREE.Color(body).multiplyScalar(0.6).getHex();
            const box = (w, h, d, c, x, y, z, hit) => {
                const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(c));
                m.position.set(x, y, z);
                m.castShadow = true;
                if (hit) { m.userData.entity = this; m.userData.hitbox = hit; }
                root.add(m);
                return m;
            };
            const bird = k === 'fowl';
            const legH = bird ? 0.22 : k === 'rabbit' ? 0.12 : s * (k === 'deer' ? 0.75 : k === 'cow' ? 0.5 : 0.45);
            const bw = bird ? 0.22 : s * (k === 'cow' ? 0.65 : k === 'bear' ? 0.62 : 0.42), bh = bird ? 0.22 : s * (k === 'rabbit' ? 0.7 : k === 'bear' ? 0.58 : 0.45), bl = bird ? 0.34 : s * (k === 'rabbit' ? 0.9 : 1.1);
            const by = legH + bh / 2;
            this.body = box(bw, bh, bl, body, 0, by, 0, 'torso');
            const hs = bird ? 0.13 : s * (k === 'bear' ? 0.36 : k === 'rabbit' ? 0.45 : 0.3);
            const hy = by + bh * (k === 'deer' ? 0.9 : 0.35), hz = bl / 2 + hs * 0.4;
            this.head = box(hs, hs, hs * 1.3, k === 'goat' ? 0xeee8dc : body, 0, hy, hz, 'head');
            // Face details share the grazing head pivot. Coordinates above are root-local.
            const headDetail = (w, h, d, c, x, y, z) => {
                const part = box(w, h, d, c, x - this.head.position.x, y - hy, z - hz, 'head');
                this.head.add(part);
            };
            if (k === 'deer') box(s * 0.16, s * 0.5, s * 0.16, body, 0, by + bh * 0.55, bl / 2 - 0.05, 'torso');
            for (const side of [-1, 1]) {
                if (k === 'deer') headDetail(0.04, 0.35, 0.04, 0xd8c8a8, side * 0.1, hy + 0.3, hz - 0.05);
                if (k === 'goat') headDetail(0.05, 0.22, 0.05, 0x5a5048, side * 0.07, hy + 0.17, hz - 0.08);
                if (k === 'boar') headDetail(0.04, 0.04, 0.16, 0xeee8d0, side * 0.09, hy - 0.08, hz + 0.18);
                if (k === 'cow') headDetail(0.05, 0.18, 0.05, 0xd8d0b8, side * 0.15, hy + 0.15, hz);
                if (k === 'rabbit') headDetail(0.05, 0.2, 0.04, body, side * 0.05, hy + 0.17, hz - 0.03);
            }
            if (bird) {
                headDetail(0.05, 0.05, 0.08, 0xd8a03a, 0, hy - 0.02, hz + 0.1);
                box(0.08, 0.12, 0.24, 0x5a3a20, 0, by + 0.06, -bl / 2 - 0.1, 'limb');
            }
            if (k === 'wolf') box(0.08, 0.08, s * 0.5, dark, 0, by + 0.05, -bl / 2 - s * 0.2, 'limb');
            this.legs = [];
            const lw = bird ? 0.03 : Math.max(0.05, s * 0.13);
            for (const lz of (bird ? [0] : [1, -1])) {
                for (const lx of [1, -1]) {
                    const pivot = new THREE.Group();
                    pivot.position.set(lx * (bird ? 0.06 : bw / 2 - lw / 2), legH, lz * (bl / 2 - lw));
                    const leg = box(lw, legH, lw, bird ? 0xd8a03a : dark, 0, -legH / 2, 0, 'limb');
                    pivot.add(leg);
                    root.add(pivot);
                    this.legs.push(pivot);
                }
            }
            this.height = by + bh;
            this.radius = Math.max(0.25, bw * 0.7);
            this.root = root;
            this.parts = { root, headGroup: this.head };
            BO.Hitboxes.prepare(this, this.parts);
            root.position.copy(this.pos);
            BO.SurvivalMode.scene.add(root);
        }

        getHitboxMeshes(out = []) { return this.alive ? BO.Hitboxes.collect(this, out) : out; }

        destroy() {
            BO.Hitboxes?.dispose?.(this);
            this.root.removeFromParent();
            this.root.traverse((o) => { o.geometry?.dispose?.(); o.material?.dispose?.(); });
        }
    }

    class ZoneWild {
        constructor() { this.animals = []; }
        get campaign() { return this.mode?.campaign; }

        start(mode, saved) {
            this.stop();
            this.mode = mode;
            this.animals = [];
            this.serial = 0;
            this.spawnClock = 2;
            this.regenUntil = 0;
            this.objects = [];
            this.claimed = new Set(saved?.claimed || []);
            this.weaponsTaken = new Set(saved?.weaponsTaken || []);
            this.boxOpen = false;
            this.spyglassOpen = false;
            this.spyglassZoom = 0;
            this.spyglassTargetZoom = 4.5;
            this.ramCd = new Map();
            this.noiseTick = 0;
            BO.Player._survGrenades = saved?.grenades ? { ...saved.grenades } : { frag: BO.Player.lethalCount || 0, napalm: 0 };
            this.placeVehicles();
            this.placeWeapons();
            if (mode.campaign.has('sv_master_box')) this.placeMasterBox();
            this.installOnce();
        }

        stop() {
            for (const a of this.animals) a.destroy();
            this.animals = [];
            for (const o of this.objects || []) o.removeFromParent?.();
            this.objects = [];
            this.closeBox();
            this.setSpyglass(false);
            this.spyEl?.remove();
            this.spyEl = null;
            this.mode = null;
        }

        snapshot() {
            const g = BO.Player?._survGrenades || { frag: 0, napalm: 0 };
            return { claimed: [...this.claimed], weaponsTaken: [...this.weaponsTaken], grenades: { frag: g.frag || 0, napalm: g.napalm || 0 } };
        }

        installOnce() {
            if (this._installed) return;
            this._installed = true;
            const C = BO.SurvivalCampaign.prototype;
            const station = C.stationAvailable;
            const ALT = { campfire: ['firepit', 'cookstation', 'smoker'], bench: ['tanrack'] };
            C.stationAvailable = function (type) {
                if (station.call(this, type)) return true;
                return !!ALT[type] && ALT[type].some((t) => station.call(this, t));
            };
            const stations = Object.getOwnPropertyDescriptor(C, 'stations');
            if (stations?.get) Object.defineProperty(C, 'stations', { configurable: true, get() { return ['hand', 'bench', 'campfire', 'kiln', 'cookstation'].filter((t) => this.stationAvailable(t)); } });
            // Build-only vehicles come out of the crafting menu.
            const P = BO.SurvivalPack?.prototype || (BO.SurvivalMode.campaign && Object.getPrototypeOf(BO.SurvivalMode.campaign.pack));
            if (P?.craft) {
                const craft = P.craft;
                P.craft = function (id) {
                    const ok = craft.call(this, id);
                    const rec = ok && this.recipe(id);
                    if (rec?.vehicle) {
                        this.campaign.vehicles.add(rec.vehicle);
                        this.campaign.mark('vehiclesBuilt', 1, 60);
                        BO.Events.emit('hud:banner', { title: 'VEHICLE BUILT', sub: (BO.SurvivalCampaignData.vehicles.find((v) => v.id === rec.vehicle)?.name || '').toUpperCase() + ' · PRESS ' + BO.Settings.keyLabel(BO.Settings.getKeybinds().survRide || 'KeyN') + ' TO RIDE', color: '#8fe3c8' });
                    }
                    if (ok && /^cook_|^batchRoast|^stew|^meatPie|^omelette|^soup|^berryPie|^honeyHam|^feast|^goldenRation|^jerky/.test(id)) this.campaign.mark('meals', 1, 6);
                    return ok;
                };
            }
            // Vehicle models for the new kinds (mounted = true keeps roofs/cabs clear of 1st-person eye height).
            const build = C.buildVehicleModel;
            C.buildVehicleModel = function (id) {
                const spec = BO.SurvivalCampaignData.vehicles.find((v) => v.id === id);
                if (spec?.kind && !['bike', 'horse'].includes(spec.kind) && !(spec.kind === 'car' && id === 'rover')) return BO.ZoneWild.vehicleModel(this.mode, spec, true);
                return build.call(this, id === 'mule' ? 'mount' : id);
            };
        }

        /* ------------------------------------------------------------ population */
        cap() {
            const c = this.campaign;
            return c.has('sv_no_animals') ? 0 : 11 + (c.isNight ? 2 : 0);
        }

        pickSpecies(x, z) {
            const biome = BO.Zone.regionAt(x, z).biome;
            const night = this.campaign.isNight;
            const opts = Object.entries(SPECIES).map(([k, s]) => [k, (s.biomes[biome] || 0) * (k === 'wolf' && night ? s.night : 1)]).filter(([, w]) => w > 0);
            if (!opts.length) return null;
            const total = opts.reduce((a, [, w]) => a + w, 0);
            let r = Math.random() * total;
            for (const [k, w] of opts) { r -= w; if (r <= 0) return k; }
            return opts[0][0];
        }

        spawnAround() {
            const p = BO.Player.pos;
            const nav = BO.World.nav;
            for (let t = 0; t < 10; t++) {
                const a = Math.random() * Math.PI * 2, d = 55 + Math.random() * 70;
                const x = p.x + Math.cos(a) * d, z = p.z + Math.sin(a) * d;
                const j = nav?.idx(x, z) ?? -1;
                if (j < 0 || !nav.walk[j] || BO.Zone.inReservoir(x, z)) continue;
                if (BO.Zone.regionAt(x, z).threat >= 5) continue;
                const kind = this.pickSpecies(x, z);
                if (!kind) continue;
                const n = SPECIES[kind].pack ? rnd(...SPECIES[kind].pack) : (kind === 'deer' || kind === 'goat' || kind === 'cow' ? rnd(1, 3) : 1);
                for (let i = 0; i < n; i++) {
                    const ax = x + (Math.random() - 0.5) * 6, az = z + (Math.random() - 0.5) * 6;
                    const y = BO.World.getGroundHeight(ax, az, BO.World.terrainHeight(ax, az) + 2);
                    this.animals.push(new Animal(++this.serial, kind, ax, y, az));
                }
                this.mode.refreshTargets();
                return;
            }
        }

        /* ------------------------------------------------------------ AI */
        update(dt) {
            const m = this.mode;
            if (!m || !m.active) return;
            const p = BO.Player;
            if (this.regenUntil > m.clock && p.alive && p.hp < p.maxHp) p.hp = Math.min(p.maxHp, p.hp + 2 * dt);
            this.syncGrenadeBelt(p);
            this.updateVehiclePhysics(dt, m, p);
            this.updateSpyglass(dt, m, p);
            this.spawnClock -= dt;
            if (this.spawnClock <= 0) {
                this.spawnClock = 4;
                const near = this.animals.filter((a) => a.alive && a.pos.distanceTo(p.pos) < 140).length;
                if (near < this.cap()) this.spawnAround();
            }
            const noises = (BO.ZoneDirector.noises || []).filter((n) => m.clock - n.t < 0.6);
            for (let i = this.animals.length - 1; i >= 0; i--) {
                const a = this.animals[i];
                const d = a.pos.distanceTo(p.pos);
                if (!a.alive) {
                    a.deathTimer -= dt;
                    if (a.deathTimer <= 0) { a.destroy(); this.animals.splice(i, 1); }
                    continue;
                }
                if (d > 185) { a.destroy(); this.animals.splice(i, 1); continue; }
                a.root.visible = d < 160;
                if (d > 110 && (m.clock * 10 + a.id) % 3 > 1) continue; // far animals tick less often
                this.think(a, d, dt, noises);
            }
        }

        think(a, d, dt, noises) {
            const m = this.mode;
            const p = BO.Player;
            const s = a.spec;
            a.timer -= dt;
            a.attackCd -= dt;
            const hostileTemper = s.temper === 'hunt' ? (this.campaign.isNight || d < 26) : s.temper === 'territorial' ? d < 15 : false;
            if (a.state !== 'attack' && p.alive && hostileTemper && !this.campaign.has('sv_passive_enemies')) a.state = 'attack';
            if (s.scare && a.state === 'wander') {
                const crouch = p.crouching ? 0.45 : 1;
                if (d < s.scare * crouch) this.flee(a, p.pos);
                else for (const n of noises) if (Math.hypot(n.x - a.pos.x, n.z - a.pos.z) < n.radius * 0.8) { this.flee(a, n); break; }
            }
            let speed = 0, tx = null, tz = null;
            if (a.state === 'attack') {
                if (!p.alive || d > 60) { a.state = 'wander'; }
                else {
                    tx = p.pos.x; tz = p.pos.z; speed = s.speed;
                    if (d < 1.4 + a.radius && a.attackCd <= 0) {
                        a.attackCd = 1.3;
                        p.takeDamage(Math.round((s.dmg || 8) * (m.difficultyRules?.damage || 1)), a.pos, false);
                        BO.ZoneDirector.onPlayerHurt?.();
                        BO.Sound?.playZombieGroan?.(a.kind === 'bear' ? 'roar_heavy' : 'growl_beast', 0.4);
                        if (s.temper === 'defend' && Math.random() < 0.35) this.flee(a, p.pos);
                    }
                }
            } else if (a.state === 'flee') {
                if (a.timer <= 0) a.state = 'wander';
                else { tx = a.goal.x; tz = a.goal.z; speed = s.speed; }
            }
            if (a.state === 'wander') {
                if (!a.goal || a.timer <= 0) {
                    a.timer = 4 + Math.random() * 6;
                    const ang = Math.random() * Math.PI * 2, r = 3 + Math.random() * 10;
                    a.goal = Math.random() < 0.35 ? null : { x: a.pos.x + Math.cos(ang) * r, z: a.pos.z + Math.sin(ang) * r };
                }
                if (a.goal && Math.hypot(a.goal.x - a.pos.x, a.goal.z - a.pos.z) > 0.6) { tx = a.goal.x; tz = a.goal.z; speed = s.speed * 0.25; }
            }
            if (tx !== null && speed > 0) {
                const want = Math.atan2(tx - a.pos.x, tz - a.pos.z);
                let diff = ((want - a.yaw + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
                a.yaw += BO.Math.clamp(diff, -6 * dt, 6 * dt);
                const nx = a.pos.x + Math.sin(a.yaw) * speed * dt, nz = a.pos.z + Math.cos(a.yaw) * speed * dt;
                const nav = BO.World.nav;
                const j = nav?.idx(nx, nz) ?? -1;
                const B = BO.Zone.BOUNDS;
                if (j < 0 || !nav.walk[j] || BO.Zone.inReservoir(nx, nz) || nx < B.minX + 4 || nx > B.maxX - 4 || nz < B.minZ + 4 || nz > B.maxZ - 4) {
                    a.yaw += Math.PI * (0.5 + Math.random() * 0.5);
                    if (a.state === 'wander') a.goal = null;
                } else {
                    a.pos.x = nx; a.pos.z = nz;
                    a.pos.y = BO.World.getGroundHeight(nx, nz, a.pos.y + 1.2);
                }
                a.phase += dt * speed * 3;
            }
            const swing = speed > 0 ? Math.sin(a.phase) * Math.min(0.7, speed * 0.12) : 0;
            a.legs.forEach((l, i) => { l.rotation.x = (i % 2 === (i < 2 ? 0 : 1) ? swing : -swing); });
            a.root.position.copy(a.pos);
            a.root.rotation.y = a.yaw;
            if (a.head && speed === 0 && a.state === 'wander') a.head.rotation.x = 0.5 + Math.sin(m.clock + a.id) * 0.2; // grazing
            else if (a.head) a.head.rotation.x = 0;
        }

        flee(a, from) {
            a.state = 'flee';
            a.timer = 5 + Math.random() * 3;
            const ang = Math.atan2(a.pos.x - from.x, a.pos.z - from.z) + (Math.random() - 0.5) * 0.8;
            a.goal = { x: a.pos.x + Math.sin(ang) * 40, z: a.pos.z + Math.cos(ang) * 40 };
        }

        /** Called by SurvivalMode.hit for animals. */
        hitAnimal(a, amount, hitbox, dir, kind, agent) {
            if (!a.alive) return false;
            const m = this.mode;
            if (!agent && BO.ZoneThrill?.active) amount = BO.ZoneThrill.modifyHit(a, amount, hitbox, kind);
            a.hp -= amount;
            BO.FX.spawnParticles(a.pos.clone().setY(a.pos.y + a.height * 0.7), 6, 0x8a1a1a, 2.5, 4, 0.4);
            if (a.hp > 0) {
                const s = a.spec;
                if (s.temper === 'flee') this.flee(a, BO.Player.pos);
                else a.state = 'attack';
                return false;
            }
            a.alive = false;
            a.deathTimer = 25;
            a.root.rotation.z = Math.PI / 2;
            a.root.position.y += a.height * 0.2;
            const drops = {};
            for (const [id, [lo, hi]] of Object.entries(a.spec.drops)) { const n = rnd(lo, hi); if (n > 0) drops[id] = n; }
            const mult = (this.campaign.has('richLoot') ? 1.5 : 1) * (this.campaign.has('sv_double_loot') ? 2 : 1);
            for (const k of Object.keys(drops)) drops[k] = Math.max(1, Math.round(drops[k] * mult));
            BO.GM?.call('onHunt', a, drops);
            if (!agent) {
                this.campaign.pack.dropBag(drops, { x: a.pos.x, y: a.pos.y, z: a.pos.z });
                this.campaign.mark('hunted', 1, 0);
                this.campaign.mark('hunt_' + a.kind, 1, 0);
                BO.ZoneThrill?.xp(a.spec.xp, a.spec.name);
                m.toast(a.spec.name + ' down — collect the drop: ' + BO.SurvivalItemAmounts(drops) + '.');
            }
            m.refreshTargets();
            return true;
        }

        /* ------------------------------------------------------------ eating & using */
        /** undefined = not ours; true/false = handled. */
        consume(id) {
            const m = this.mode;
            if (!m) return undefined;
            const pts = m.points;
            const p = BO.Player;
            const deep = this.campaign.deep;
            const fd = FOOD[id];
            if (fd) {
                if (!(pts[id] > 0)) return false;
                const needs = this.campaign.options.survivalNeeds !== false && !this.campaign.has('sv_no_hunger');
                if (needs && m.hunger >= 99.5 && p.hp >= p.maxHp && !fd.w) { m.toast('You are full.'); return false; }
                pts[id]--;
                const bonus = this.campaign.placed.some((x) => x.alive && x.type === 'smoker' && Math.hypot(x.x - p.pos.x, x.z - p.pos.z) < 8) ? 1.25 : 1;
                m.hunger = Math.min(100, m.hunger + fd.f * bonus);
                p.hp = Math.min(p.maxHp, p.hp + (fd.h || 0) * bonus);
                if (deep && fd.w) deep.hydration = Math.min(100, deep.hydration + fd.w);
                if (deep && fd.warm) { deep.temp = Math.max(deep.temp, 24); deep.comfortUntil = m.clock + 180; }
                if (fd.comp) m.composure = Math.min(100, m.composure + fd.comp);
                if (fd.stam) p.tacStamina = 1;
                if (fd.regen) this.regenUntil = Math.max(this.regenUntil, m.clock) + fd.regen;
                this.campaign.mark('eaten', 1, 0);
                let msg = 'Ate ' + BO.SurvivalItemName(id) + ' (+' + Math.round(fd.f * bonus) + ' food' + (fd.h ? ', +' + Math.round(fd.h * bonus) + ' HP' : '') + ')';
                if (fd.raw && !this.campaign.has('sv_iron_gut') && Math.random() < 0.3) {
                    if (deep) { deep.infection = Math.min(100, (deep.infection || 0) + 10); deep.hydration = Math.max(0, deep.hydration - 12); }
                    msg += '. Ugh — food poisoning. Cook your food next time (3× the value, no sickness)';
                }
                m.toast(msg + '.');
                return true;
            }
            const take = () => { if (!(pts[id] > 0)) return false; pts[id]--; return true; };
            switch (id) {
                case 'leather_armor': case 'hide_armor': case 'obsidian_armor': {
                    const maxA = id === 'obsidian_armor' ? 180 : Math.max(p.maxArmor || 150, 150);
                    if (p.armor >= maxA) { m.toast('Your armour is already full.'); return false; }
                    if (!take()) return false;
                    p.maxArmor = maxA;
                    const gain = id === 'leather_armor' ? 60 : id === 'hide_armor' ? 100 : 140;
                    p.armor = Math.min(maxA, (p.armor || 0) + gain);
                    m.toast((id === 'obsidian_armor' ? 'Obsidian trauma rig fitted' : 'Armour on') + ' (+' + gain + ').');
                    return true;
                }
                case 'frag_grenade': case 'molotov': {
                    if (!take()) return false;
                    const kind = id === 'molotov' ? 'napalm' : 'frag';
                    const belt = (p._survGrenades = p._survGrenades || { frag: p.lethalCount || 0, napalm: 0 });
                    // If held in hand in 3D (terminal closed), hurl it immediately! Otherwise arm onto lethal belt.
                    if (!BO.SurvivalUI?.open && p.survivalProp?.id === id && BO.Combat?._spawnGrenade) {
                        const spec = BO.AttachmentsData.LETHALS[kind];
                        if (spec) {
                            BO.Combat._spawnGrenade(kind, spec.fuseTime || 2.2, spec);
                            BO.Sound?.playMelee?.();
                            return true;
                        }
                    }
                    belt[kind] = (belt[kind] || 0) + 1;
                    p.lethalId = kind;
                    p.lethalCount = belt[kind];
                    m.toast('Armed ' + (id === 'molotov' ? 'firebomb' : 'frag grenade') + ' (' + belt[kind] + ' on belt · press ' + BO.Settings.keyLabel(BO.Settings.getKeybinds().lethal) + ' to throw).');
                    return true;
                }
                case 'candle':
                    if (!take()) return false;
                    this.campaign.pack.lightKind = 'candle';
                    this.campaign.pack.lightUntil = Math.max(this.campaign.pack.lightUntil, m.clock) + 240;
                    m.toast('Candle lit for 4 minutes.');
                    return true;
                case 'spyglass': {
                    if (!(pts.spyglass > 0)) return false;
                    if (BO.SurvivalUI?.open) BO.SurvivalUI.close();
                    this.setSpyglass(!this.spyglassOpen);
                    return true;
                }
                case 'bedroll': {
                    if (!(pts.bedroll > 0)) return false;
                    if (!this.campaign.canSave()) { m.toast('Too dangerous to sleep here.'); return false; }
                    const h = this.campaign.hour;
                    const until = h >= 6 && h < 19 ? 3 : ((30 - h) % 24);
                    this.campaign.restHours += until;
                    m.composure = 100;
                    m.toast('You slept rough for ' + Math.round(until) + ' hours.');
                    return true;
                }
                case 'fireworks':
                    if (!take()) return false;
                    BO.ZoneDirector.noise(p.pos.x, p.pos.z, 200, 'fireworks');
                    BO.ZoneEvents?.trigger?.('airdrop');
                    BO.FX.spawnExplosion(p.pos.clone().setY(p.pos.y + 30), 4, 0xff5ad8);
                    m.toast('Fireworks! A plane is on its way — and so is everything that heard it.');
                    return true;
            }
            return undefined;
        }

        /* ------------------------------------------------------------ station visuals */
        decorate(piece) {
            const m = this.mode;
            if (!m) return;
            const { x, y, z } = piece;
            if (piece.type === 'firepit') {
                for (let i = 0; i < 8; i++) { const a = i / 8 * Math.PI * 2; m.mesh(new THREE.DodecahedronGeometry(0.2), 0x7a7470, x + Math.cos(a) * 0.7, y + 0.15, z + Math.sin(a) * 0.7); }
                for (let i = 0; i < 3; i++) { const log = m.mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.9, 6), 0x5a3a20, x, y + 0.2, z); log.rotation.z = Math.PI / 2; log.rotation.y = i * 1.05; }
                m.mesh(new THREE.ConeGeometry(0.32, 0.8, 6), 0xff7a1a, x, y + 0.55, z, { emissive: 0xff6a00, emissiveIntensity: 1.2, transparent: true, opacity: 0.85 });
                this.campaign.pack.addLight?.(piece.id, { ...piece, y: piece.y + 0.6 });
            } else if (piece.type === 'cookstation') {
                m.mesh(new THREE.CylinderGeometry(0.22, 0.2, 0.28, 10), 0x30302e, x - 0.25, y + 1.08, z, { metalness: 0.7 });
                m.mesh(new THREE.BoxGeometry(0.5, 0.04, 0.5), 0x222222, x + 0.3, y + 0.97, z, { metalness: 0.8 });
                m.mesh(new THREE.BoxGeometry(0.4, 0.2, 0.05), 0xff6a1a, x, y + 0.35, z + 0.41, { emissive: 0xff5a00, emissiveIntensity: 1 });
                m.mesh(new THREE.CylinderGeometry(0.08, 0.08, 1.2, 6), 0x3a3a3a, x + 0.45, y + 1.5, z - 0.25);
            } else if (piece.type === 'tanrack') {
                m.mesh(new THREE.BoxGeometry(1.1, 0.9, 0.04), 0xb48a5a, x, y + 0.95, z);
            } else if (piece.type === 'smoker') {
                m.mesh(new THREE.ConeGeometry(0.9, 0.7, 4), 0x4a3a30, x, y + 2.25, z).rotation.y = Math.PI / 4;
            }
        }

        /* ------------------------------------------------------------ belt, spyglass & vehicle physics */
        syncGrenadeBelt(p) {
            const belt = (p._survGrenades = p._survGrenades || { frag: p.lethalCount || 0, napalm: 0 });
            const cur = p.lethalId === 'napalm' ? 'napalm' : 'frag';
            if (p.lethalId !== 'frag' && p.lethalId !== 'napalm') p.lethalId = 'frag';
            if ((p.lethalCount || 0) !== belt[cur]) {
                // Player threw a grenade via [G] (or picked up grenades from Box of Wonders)
                belt[cur] = Math.max(0, p.lethalCount || 0);
            }
            if (belt[cur] <= 0) {
                const other = cur === 'frag' ? 'napalm' : 'frag';
                if (belt[other] > 0) {
                    p.lethalId = other;
                    p.lethalCount = belt[other];
                }
            }
        }

        setSpyglass(on) {
            const m = this.mode;
            if (!m) return;
            this.spyglassOpen = !!on;
            if (!on) {
                this.spyglassZoom = 0;
                if (this.spyEl) this.spyEl.hidden = true;
                return;
            }
            this.spyglassTargetZoom = this.spyglassTargetZoom || 4.5;
            this.spyglassZoom = this.spyglassTargetZoom;
            const p = BO.Player;
            let marked = 0;
            for (const s of BO.ZoneInfest?.sites || []) if (!s.seen && Math.hypot(s.x - p.pos.x, s.z - p.pos.z) < 280) { s.seen = true; marked++; }
            if (marked > 0) m.toast('Spyglass recon: marked ' + marked + ' infested site' + (marked === 1 ? '' : 's') + ' on map.');
            BO.Sound?.playUIClick?.();
        }

        adjustSpyglassZoom(dir) {
            if (!this.spyglassZoom) return false;
            this.spyglassTargetZoom = BO.Math.clamp(Number(((this.spyglassTargetZoom || 4.5) + dir * 1.0).toFixed(1)), 2.5, 10.0);
            this.spyglassZoom = this.spyglassTargetZoom;
            return true;
        }

        updateSpyglass(dt, m, p) {
            const holdingSpyglass = p.usingBareHands && p.survivalProp?.id === 'spyglass' && (m.points.spyglass || 0) > 0;
            const wantAds = holdingSpyglass && p.adsHeld;
            if (this.spyglassOpen && (!p.alive || m.rider || BO.SurvivalUI?.open || !(m.points.spyglass > 0))) {
                this.spyglassOpen = false;
            }
            const active = this.spyglassOpen || wantAds;
            if (!active) {
                this.spyglassZoom = 0;
                if (this.spyEl && !this.spyEl.hidden) this.spyEl.hidden = true;
                return;
            }
            this.spyglassZoom = this.spyglassTargetZoom || 4.5;
            if (!this.spyEl) {
                this.spyEl = document.createElement('div');
                this.spyEl.className = 'zt-spyglass';
                this.spyEl.innerHTML = `<div class="zt-spy-ring"><div class="zt-spy-cross"></div><div class="zt-spy-ticks"></div></div>
                    <div class="zt-spy-readout"><b class="zt-spy-tgt">SCANNING HORIZON</b><span class="zt-spy-sub">4.5× OPTIC · WHEEL TO ZOOM · ESC / RMB TO LOWER</span></div>`;
                document.body.appendChild(this.spyEl);
            }
            this.spyEl.hidden = false;
            if (m.camera) {
                const aim = p.getAimRay(m.camera);
                const worldHit = BO.World.raycastWorld(aim.origin, aim.dir, 420);
                let dist = worldHit ? Math.round(worldHit.distance) : null;
                let label = '';
                let bestDot = 0.985;
                const checkTarget = (x, y, z, text) => {
                    const dx = x - aim.origin.x, dy = y - aim.origin.y, dz = z - aim.origin.z;
                    const d = Math.hypot(dx, dy, dz);
                    if (d < 2 || d > 360) return;
                    const dot = (dx * aim.dir.x + dy * aim.dir.y + dz * aim.dir.z) / d;
                    if (dot > bestDot) { bestDot = dot; dist = Math.round(d); label = text; }
                };
                for (const z of m.zombies) if (z.alive) checkTarget(z.pos.x, z.pos.y + 1.1, z.pos.z, (z.bossLabel || z.champName || z.spec?.name || 'Infected') + ' · ' + Math.ceil(z.hp) + ' HP');
                for (const a of this.animals) if (a.alive) checkTarget(a.pos.x, a.pos.y + a.height * 0.6, a.pos.z, a.spec.name + (a.kind === 'wolf' || a.kind === 'boar' || a.kind === 'bear' ? ' · Tameable' : ''));
                for (const mk of m.markers) if (mk.alive !== false && (mk.dungeon || mk.vehicle || mk.kind === 'tower' || mk.pit)) checkTarget(mk.x, (mk.y || 0) + 1.4, mk.z, mk.name);
                if (!label) {
                    for (const poi of BO.Zone.pois) {
                        const dx = poi.x - aim.origin.x, dz = poi.z - aim.origin.z;
                        const d = Math.hypot(dx, dz);
                        if (d < 400 && (dx * aim.dir.x + dz * aim.dir.z) / Math.max(1, d) > 0.97) {
                            label = (poi.name || poi.type.replace(/_/g, ' ')) + ' (Tier ' + (poi.tier || 1) + ')';
                            if (dist == null) dist = Math.round(d);
                            break;
                        }
                    }
                }
                const tgtEl = this.spyEl.querySelector('.zt-spy-tgt');
                const subEl = this.spyEl.querySelector('.zt-spy-sub');
                const head = (label || BO.Zone.regionAt(p.pos.x, p.pos.z).name) + (dist != null ? ' · ' + dist + ' m' : '');
                const sub = this.spyglassZoom.toFixed(1) + '× RECON · ' + this.animals.filter((a) => a.alive && a.pos.distanceTo(p.pos) < 160).length + ' WILDLIFE NEARBY · WHEEL ZOOM';
                if (tgtEl.textContent !== head) tgtEl.textContent = head.toUpperCase();
                if (subEl.textContent !== sub) subEl.textContent = sub;
            }
        }

        updateVehiclePhysics(dt, m, p) {
            const c = this.campaign;
            if (!c?.vehicle || !p.alive) return;
            const spec = BO.SurvivalCampaignData.vehicles.find((v) => v.id === c.vehicle);
            if (!spec) return;
            const horiz = Math.hypot(p.vel.x, p.vel.z);
            this.noiseTick -= dt;
            if (horiz > 2.2 && spec.noise > 0 && this.noiseTick <= 0) {
                this.noiseTick = 0.45;
                m.noise = Math.max(m.noise || 0, Math.min(9, spec.noise * 1.15));
                BO.ZoneDirector?.noise?.(p.pos.x, p.pos.z, 18 + spec.noise * 18, 'vehicle');
            }
            // Vehicle ramming: hitting infected at speed knocks them down and crushes them based on vehicle mass!
            if (horiz < 6.2) return;
            const heavy = ['truck', 'apc', 'tractor', 'car'].includes(spec.kind);
            const med = ['quad', 'moto', 'sled', 'mono', 'kart'].includes(spec.kind);
            const ramRadius = heavy ? 1.85 : med ? 1.35 : 1.05;
            const massMult = heavy ? 11.5 : med ? 7.0 : 4.2;
            const fwd = p.getMoveDirectionVectors().forward;
            for (const zb of m.zombies) {
                if (!zb.alive) continue;
                const lastHit = this.ramCd.get(zb) ?? -99;
                if (m.clock - lastHit < 0.75) continue;
                const dx = zb.pos.x - p.pos.x, dz = zb.pos.z - p.pos.z;
                const d = Math.hypot(dx, dz);
                if (d > ramRadius + (zb.radius || 0.45) || Math.abs(zb.pos.y - p.pos.y) > 2.0) continue;
                if (d > 0.3 && (dx * fwd.x + dz * fwd.z) / d < 0.25) continue;
                this.ramCd.set(zb, m.clock);
                const dmg = Math.round(horiz * massMult);
                const killed = m.hit(zb, dmg, 'torso', fwd, 'melee', null);
                if (zb.alive) {
                    zb.pos.x += fwd.x * (heavy ? 2.4 : 1.4);
                    zb.pos.z += fwd.z * (heavy ? 2.4 : 1.4);
                    zb.stunTimer = Math.max(zb.stunTimer || 0, heavy ? 1.2 : 0.6);
                } else if (killed) {
                    c.mark('roadkills', 1, 12);
                }
                p.cameraShake = Math.max(p.cameraShake || 0, heavy ? 0.04 : 0.025);
                BO.Sound?.playMeleeHit?.();
                BO.FX?.spawnParticles?.(zb.pos.clone().setY(zb.pos.y + 0.9), 8, 0x991b1b, 3.5, 8, 0.4);
            }
        }

        /* ------------------------------------------------------------ vehicles */
        vehicleModel(m, spec, mounted = false) {
            const g = new THREE.Group();
            const c = spec.color;
            const box = (w, h, d, col, x, y, z) => { const mesh = m.mesh(new THREE.BoxGeometry(w, h, d), col, x, y, z); g.add(mesh); return mesh; };
            const wheel = (r, w, x, y, z) => { const mesh = m.mesh(new THREE.CylinderGeometry(r, r, w, 12), 0x23282a, x, y, z); mesh.rotation.z = Math.PI / 2; g.add(mesh); return mesh; };
            switch (spec.kind) {
                case 'moto': wheel(0.32, 0.12, 0, 0.32, -0.7); wheel(0.32, 0.12, 0, 0.32, 0.55); box(0.28, 0.3, 1.1, c, 0, 0.62, -0.05); box(0.6, 0.06, 0.06, 0x333333, 0, 0.98, -0.6); break;
                case 'quad': for (const sx of [-1, 1]) for (const z of [-0.6, 0.55]) wheel(0.3, 0.25, sx * 0.5, 0.3, z); box(0.8, 0.35, 1.4, c, 0, 0.62, 0); box(0.7, 0.06, 0.06, 0x333333, 0, 1.0, -0.6); break;
                case 'car':
                    for (const sx of [-1, 1]) for (const z of [-0.95, 0.95]) wheel(0.36, 0.22, sx * 0.85, 0.36, z);
                    box(1.7, 0.52, 3.2, c, 0, 0.68, 0);
                    if (!mounted) box(1.5, 0.5, 1.4, new THREE.Color(c).multiplyScalar(0.8).getHex(), 0, 1.3, 0.2);
                    else box(1.4, 0.08, 0.35, 0x262c30, 0, 0.98, -0.82);
                    break;
                case 'truck':
                    for (const sx of [-1, 1]) for (const z of [-1.3, 1.2]) wheel(0.42, 0.26, sx * 0.95, 0.42, z);
                    box(1.9, 0.66, 3.9, c, 0, 0.8, 0);
                    if (!mounted) box(1.8, 0.7, 1.3, c, 0, 1.7, -0.95);
                    else box(1.6, 0.1, 0.42, 0x262c30, 0, 1.12, -1.05);
                    break;
                case 'apc':
                    for (const sx of [-1, 1]) for (const z of [-1.3, 0, 1.3]) wheel(0.45, 0.3, sx * 1.05, 0.45, z);
                    if (!mounted) {
                        box(2.0, 1.2, 4.2, c, 0, 1.2, 0);
                        box(0.6, 0.35, 0.6, 0x2a2a2a, 0, 2.0, 0.2);
                        box(0.1, 0.1, 1.2, 0x2a2a2a, 0, 2.05, -0.6);
                    } else {
                        box(2.0, 0.68, 4.2, c, 0, 0.76, 0);
                        box(0.12, 0.12, 1.1, 0x2a2a2a, 0.55, 1.12, -1.35);
                    }
                    break;
                case 'sled': box(0.8, 0.4, 1.8, c, 0, 0.5, 0); box(0.12, 0.06, 2.0, 0x222222, 0.35, 0.12, 0); box(0.12, 0.06, 2.0, 0x222222, -0.35, 0.12, 0); box(0.6, 0.06, 0.06, 0x333333, 0, 0.98, -0.6); break;
                case 'tractor':
                    wheel(0.6, 0.3, 0.7, 0.6, 0.5); wheel(0.6, 0.3, -0.7, 0.6, 0.5); wheel(0.32, 0.2, 0.55, 0.32, -0.9); wheel(0.32, 0.2, -0.55, 0.32, -0.9);
                    box(0.8, 0.55, 1.8, c, 0, 0.85, -0.2);
                    if (!mounted) box(0.9, 0.9, 0.8, 0x222222, 0, 1.6, 0.4);
                    break;
                case 'cart':
                    for (const sx of [-1, 1]) for (const z of [-0.7, 0.7]) wheel(0.22, 0.14, sx * 0.55, 0.22, z);
                    box(1.1, 0.3, 1.9, c, 0, 0.45, 0);
                    if (!mounted) {
                        box(1.1, 0.05, 1.1, c, 0, 1.6, 0.1);
                        for (const sx of [-1, 1]) box(0.05, 1.1, 0.05, 0x888888, sx * 0.5, 1.05, -0.4);
                    }
                    break;
                case 'kart': for (const sx of [-1, 1]) for (const z of [-0.6, 0.6]) wheel(0.2, 0.18, sx * 0.55, 0.2, z); box(0.9, 0.18, 1.6, c, 0, 0.28, 0); box(0.5, 0.3, 0.4, 0x333333, 0, 0.5, 0.45); break;
                case 'mono': {
                    if (!mounted) {
                        const w = wheel(0.95, 0.25, 0, 0.95, 0); w.rotation.z = Math.PI / 2;
                        box(0.3, 0.3, 0.3, c, 0, 0.75, 0);
                    } else {
                        for (const sx of [-0.36, 0.36]) wheel(0.52, 0.12, sx, 0.52, -0.2);
                        box(0.62, 0.22, 0.9, c, 0, 0.55, 0);
                    }
                    break;
                }
                case 'board': box(0.5, 0.06, 1.3, c, 0, 0.35, 0).material.emissive = new THREE.Color(c); box(0.35, 0.03, 0.9, 0xffffff, 0, 0.3, 0).material.emissive = new THREE.Color(0x8fe3c8); break;
                case 'sledge': box(0.9, 0.2, 2.0, c, 0, 0.25, 0); box(0.08, 0.6, 0.08, 0x6a4a2a, 0.4, 0.6, -0.9); box(0.08, 0.6, 0.08, 0x6a4a2a, -0.4, 0.6, -0.9); break;
                default: box(0.8, 0.4, 1.4, c, 0, 0.5, 0);
            }
            m.scene.add(g);
            return g;
        }

        /** Parked vehicles waiting to be claimed near their landmark buildings. */
        placeVehicles() {
            const m = this.mode;
            for (const spec of BO.SurvivalCampaignData.vehicles) {
                if (!spec.found || this.claimed.has(spec.id) || m.campaign.vehicles.has(spec.id)) continue;
                const poi = BO.Zone.pois.find((p) => p.type === spec.found);
                if (!poi) continue;
                const x = poi.x + poi.w / 2 + 3.5, z = poi.z - poi.d / 2 - 1;
                const y = BO.World.getGroundHeight(x, z, (poi.y || 0) + 2);
                const model = this.vehicleModelFor(spec);
                model.position.set(x, y, z);
                model.rotation.y = 0.6;
                this.objects.push(model);
                const marker = { id: 'veh:' + spec.id, x, y, z, name: spec.name, label: 'Claim ' + spec.name, alive: true, vehicle: spec.id, model, reach: 3 };
                m.markers.push(marker);
            }
        }

        vehicleModelFor(spec) {
            if (['bike', 'horse'].includes(spec.kind) || spec.id === 'rover') return this.campaign.buildVehicleModel(spec.id === 'mule' ? 'mount' : spec.id);
            return this.vehicleModel(this.mode, spec);
        }

        claim(marker) {
            const c = this.campaign;
            c.vehicles.add(marker.vehicle);
            this.claimed.add(marker.vehicle);
            marker.alive = false;
            marker.model?.removeFromParent();
            c.mark('vehiclesClaimed', 1, 40);
            const spec = BO.SurvivalCampaignData.vehicles.find((v) => v.id === marker.vehicle);
            BO.Events.emit('hud:banner', { title: 'VEHICLE CLAIMED', sub: spec.name.toUpperCase() + ' · PRESS ' + BO.Settings.keyLabel(BO.Settings.getKeybinds().survRide || 'KeyN') + ' TO RIDE · MAP LISTS ALL YOUR VEHICLES', color: '#8fe3c8' });
            c.ride(marker.vehicle);
        }

        /** Ride key: dismount, or mount the fastest vehicle you own. Shift + Ride cycles owned vehicles! */
        toggleRide(cycle = false) {
            const c = this.campaign;
            if (!c) return false;
            const owned = BO.SurvivalCampaignData.vehicles.filter((v) => c.hasVehicle(v.id));
            if (cycle && owned.length > 1) {
                const curIdx = owned.findIndex((v) => v.id === (c.vehicle || this.lastRide));
                const next = owned[(curIdx + 1) % owned.length];
                if (c.ride(next.id)) { this.lastRide = next.id; this.mode.toast('Switched ride: ' + next.name + '.'); }
                return true;
            }
            if (c.vehicle) { c.ride(null); this.mode.toast('Dismounted.'); return true; }
            if (c.has('footOnly') || c.has('sv_no_vehicles')) { this.mode.toast('Vehicles are disabled for this expedition.'); return true; }
            if (!owned.length) { this.mode.toast('You have no vehicle yet. Claim parked ones (map) or build them at a crafting table.'); return true; }
            const pref = owned.find((v) => v.id === this.lastRide) || [...owned].sort((a, b) => b.offroad + b.speed - a.offroad - a.speed)[0];
            if (c.ride(pref.id)) { this.lastRide = pref.id; this.mode.toast('Riding the ' + pref.name + (owned.length > 1 ? ' (Shift+' + BO.Settings.keyLabel(BO.Settings.getKeybinds().survRide) + ' to cycle).' : '.')); }
            return true;
        }

        /* ------------------------------------------------------------ world weapons */
        placeWeapons() {
            const m = this.mode;
            if (m.campaign.options.resume) return; // restored with the other dropped pickups
            let i = 0;
            for (const poi of BO.Zone.pois) {
                const list = WORLD_WEAPONS[poi.region];
                if (!list || (i++ % 2)) continue;
                const id = list[Math.floor(Math.random() * list.length)];
                if (!BO.WeaponsData.get(id)) continue;
                const tier = Math.max(1, Math.min(4, poi.tier || 1));
                const roll = BO.ZoneThrill?.rollWeapon(id, tier, tier >= 3 ? 2 : 1) || null;
                m.loot.dropPickup(id, 70 + rnd(0, 25), { x: poi.x - poi.w / 2 - 1.5, y: poi.y || 0, z: poi.z + poi.d / 2 + 1 }, BO.WeaponsData.get(id).name, roll);
            }
            // A few showpieces in the wild: towers, the dam, the crater rim.
            for (const mk of m.markers.filter((x) => x.kind === 'tower' || x.kind === 'landmark').slice(0, 8)) {
                const reg = BO.Zone.regionAt(mk.x, mk.z).id;
                const list = WORLD_WEAPONS[reg] || WORLD_WEAPONS.relay;
                const id = list[Math.floor(Math.random() * list.length)];
                if (!BO.WeaponsData.get(id)) continue;
                m.loot.dropPickup(id, 85, { x: mk.x + 2, y: mk.y || 0, z: mk.z + 2 }, BO.WeaponsData.get(id).name, BO.ZoneThrill?.rollWeapon(id, 3, 2) || null);
            }
        }

        /* ------------------------------------------------------------ Box of Wonders */
        placeMasterBox() {
            const m = this.mode;
            const s = BO.Zone.map.playerSpawn;
            const x = s.x + 3, z = s.z + 2;
            const y = BO.World.getGroundHeight(x, z, BO.World.terrainHeight(x, z) + 2);
            const box = m.mesh(new THREE.BoxGeometry(1.4, 0.9, 0.9), 0x5a2a8a, x, y + 0.45, z, { emissive: 0xb46bff, emissiveIntensity: 0.6, metalness: 0.4 });
            const beam = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.5, 30, 8, 1, true), new THREE.MeshBasicMaterial({ color: new THREE.Color(0xb46bff).convertSRGBToLinear(), transparent: true, opacity: 0.45, fog: false, depthWrite: false, side: THREE.DoubleSide }));
            beam.position.set(x, y + 15, z);
            m.scene.add(beam);
            this.objects.push(box, beam);
            m.markers.push({ id: 'masterbox', x, y, z, name: 'Box of Wonders', label: 'Open the Box of Wonders', alive: true, masterbox: true, reach: 2.6 });
        }

        activate(marker) {
            if (marker?.vehicle && marker.id.startsWith('veh:')) { this.claim(marker); return true; }
            if (marker?.masterbox) { this.openBox(); return true; }
            return false;
        }

        openBox(tab = 'items') {
            this.boxOpen = { tab, q: '' };
            if (document.pointerLockElement) document.exitPointerLock();
            this.renderBox();
        }

        closeBox() {
            if (!this.boxOpen) return;
            this.boxOpen = false;
            this.boxEl?.remove();
            this.boxEl = null;
            if (BO.State.screen === 'playing') BO.App?._safePointerLock?.();
        }

        renderBox() {
            const st = this.boxOpen;
            if (!st) return;
            if (!this.boxEl) {
                this.boxEl = document.createElement('div');
                this.boxEl.className = 'zt-box';
                document.body.appendChild(this.boxEl);
                this.boxEl.addEventListener('click', (e) => this.boxClick(e));
                this.boxEl.addEventListener('input', (e) => { if (e.target.matches('input')) { st.q = e.target.value.toLowerCase(); this.renderBox(); const i = this.boxEl.querySelector('input'); i.focus(); i.setSelectionRange(i.value.length, i.value.length); } });
            }
            const items = BO.SurvivalFrontierData.items;
            let body = '';
            if (st.tab === 'items') {
                const ids = Object.keys(items).filter((id) => !st.q || items[id][0].toLowerCase().includes(st.q));
                body = ids.map((id) => `<button data-box-item="${id}" title="Take 10 (shift: 100)"><b>${esc(items[id][0])}</b><small>${esc(items[id][1])}</small></button>`).join('');
            } else if (st.tab === 'weapons') {
                const all = [...BO.WeaponsData.listGuns?.() || [], ...BO.WeaponsData.listMelee?.() || [], ...BO.WeaponsData.listMagic?.() || []].map((w) => (typeof w === 'string' ? BO.WeaponsData.get(w) : w)).filter(Boolean);
                body = all.filter((w) => !st.q || w.name.toLowerCase().includes(st.q)).map((w) => `<button data-box-weapon="${w.id}" title="Equip a Legendary copy"><b>${esc(w.name)}</b><small>${esc(w.category || '')}</small></button>`).join('');
            } else if (st.tab === 'vehicles') {
                body = BO.SurvivalCampaignData.vehicles.map((v) => `<button data-box-vehicle="${v.id}"><b>${esc(v.name)}</b><small>${this.campaign.hasVehicle(v.id) ? 'owned · click to ride' : 'click to take'}</small></button>`).join('');
            } else {
                body = ['<button data-box-gear="armor"><b>Full armour</b><small>150 armour + 3 plates</small></button>', '<button data-box-gear="grenades"><b>Grenades</b><small>+5 frags, +5 flashbangs</small></button>',
                    '<button data-box-gear="heal"><b>Full restore</b><small>Health, food, water, radiation, bleeding</small></button>', '<button data-box-gear="ammo"><b>Ammunition</b><small>500 of every calibre</small></button>',
                    '<button data-box-gear="tools"><b>Every tool</b><small>All axes, picks, spades, the drill</small></button>', '<button data-box-gear="pack"><b>Biggest backpack</b><small>Hauler frame</small></button>',
                    '<button data-box-comp="wolf"><b>Companion: Zone Hound</b><small>Tamed tracker wolf</small></button>', '<button data-box-comp="boar"><b>Companion: Tusk Charger</b><small>+12 kg saddle & knockdown</small></button>',
                    '<button data-box-comp="bear"><b>Companion: Apex War-Bear</b><small>Heavy boss-tank grizzly</small></button>', '<button data-box-comp="ranger"><b>Companion: Haven Vanguard</b><small>Suppressed rifle scout</small></button>'].join('');
            }
            this.boxEl.innerHTML = `<div class="zt-box-in"><header><b>BOX OF WONDERS</b><span>Everything, without limit. Click to take.</span><button data-box-close>Close · Esc</button></header>
                <nav>${['items', 'weapons', 'vehicles', 'gear'].map((t) => `<button data-box-tab="${t}" class="${st.tab === t ? 'on' : ''}">${t[0].toUpperCase() + t.slice(1)}</button>`).join('')}<input placeholder="Search…" value="${esc(st.q)}"></nav>
                <div class="zt-box-grid">${body}</div></div>`;
        }

        boxClick(e) {
            const m = this.mode;
            const t = e.target.closest('button');
            if (!t || !m) return;
            const d = t.dataset;
            const p = BO.Player;
            if (d.boxClose !== undefined) return this.closeBox();
            if (d.boxTab) { this.boxOpen.tab = d.boxTab; return this.renderBox(); }
            if (d.boxItem) { const n = e.shiftKey ? 100 : 10; m.points[d.boxItem] = (m.points[d.boxItem] || 0) + n; this.campaign.hotbar?.reconcile?.(); m.toast('+' + n + ' ' + BO.SurvivalItemName(d.boxItem)); return; }
            if (d.boxWeapon) {
                const slot = p.activeSlot >= 0 ? p.activeSlot : 0;
                const w = m.loot.give(d.boxWeapon, 100, p.weapons[slot] ? slot : -1, BO.ZoneThrill?.rollWeapon(d.boxWeapon, 4, 4) || null);
                if (w) { w.mag = w.stats.magSize; if (!BO.ZoneLoot.caliberOf(w)) w.reserve = w.stats.reserveMax; }
                m.toast('Equipped ' + (w?.stats.name || d.boxWeapon) + '.');
                return;
            }
            if (d.boxVehicle) { this.campaign.vehicles.add(d.boxVehicle); this.closeBox(); this.campaign.ride(d.boxVehicle); return; }
            if (d.boxComp && BO.ZoneCompanions) { this.closeBox(); BO.ZoneCompanions.spawnCompanion(d.boxComp, { x: p.pos.x + 2, y: p.pos.y, z: p.pos.z + 2 }); this.campaign.mark('companionsTamed', 1, 80); return; }
            if (d.boxGear === 'armor') { p.maxArmor = Math.max(p.maxArmor || 150, 150); p.armor = p.maxArmor; p.armorReservePlates = 3; }
            if (d.boxGear === 'grenades') { p.lethalCount = (p.lethalCount || 0) + 5; p.tacticalCount = (p.tacticalCount || 0) + 5; }
            if (d.boxGear === 'heal') { p.hp = p.maxHp; m.hunger = 100; m.radiation = 0; const dp = this.campaign.deep; if (dp) { dp.hydration = 100; dp.bleeding = 0; dp.infection = 0; } m.fracture = false; }
            if (d.boxGear === 'ammo') for (const k of ['ammo9', 'ammo556', 'ammo762', 'ammo12']) m.points[k] = (m.points[k] || 0) + 500;
            if (d.boxGear === 'tools') { const pk = this.campaign.pack; for (const [id, tl] of Object.entries(BO.SurvivalFrontierData.tools)) pk.tools[id] = tl.wear; this.campaign.hotbar?.reconcile?.(); }
            if (d.boxGear === 'pack') this.campaign.pack.level = BO.SurvivalFrontierData.packs.length - 1;
            if (d.boxGear) m.toast('Taken from the Box of Wonders.');
        }

        handleKey(e) {
            if (!this.boxOpen) return false;
            if (e.code === 'Escape') { e.preventDefault(); this.closeBox(); }
            return true;
        }
    }

    BO.ZoneWild = new ZoneWild();
    BO.ZoneWild.SPECIES = SPECIES;
    BO.ZoneWild.FOOD = FOOD;
    BO.ZoneWild.WORLD_WEAPONS = WORLD_WEAPONS;
})(window.BO);
;

/* --- src/systems/ZoneCompanions.js --- */
/* ============================================================================
   BLACKOUT OPS — Wild Zone Companions & Taming (BO.ZoneCompanions)
   · Tame wild Grey Wolves (Zone Hound), Wild Boars (Tusk Charger) and Brown
     Bears (Apex War-Bear) in the field, or recruit a Haven Vanguard ranger
     at Haven / from rescued distress survivors.
   · Tactical stances (KeyY / survCompanion): Follow & Fight · Heel (Stealth) · Guard Post
   · Ranks I–V progression, Tracker's Nose loot/intel pings, Pack Saddle carry
     bonus (+12 kg), feeding & petting, non-lethal downed recovery, and full
     checkpoint persistence.
============================================================================ */
(function (BO) {
    'use strict';

    const ARCHETYPES = {
        wolf: {
            id: 'wolf', name: 'Zone Hound', subtitle: 'Loyal Grey Wolf',
            hp: 240, speed: 7.8, dmg: 36, rate: 0.95, range: 2.1,
            color: 0x737882, accent: 0x8fe3c8,
            treats: [['cooked_venison', 2], ['cooked_beef', 2], ['cooked_pork', 2], ['bone', 1], ['raw_venison', 1], ['raw_pork', 1]],
            need: 2,
            perk: 'Tracker\'s Nose: pings nearby unsearched crates, intel & drops every 18 s.'
        },
        boar: {
            id: 'boar', name: 'Tusk Charger', subtitle: 'Armoured Wild Boar',
            hp: 330, speed: 6.8, dmg: 44, rate: 1.15, range: 2.2, stun: 1.35, carryBonus: 12,
            color: 0x4f3e34, accent: 0xf2b45a,
            treats: [['berry_pie', 2], ['roast_mushroom', 2], ['berries', 1], ['mushroom', 1]],
            need: 2,
            perk: 'Pack Saddle (+12 kg carry limit) & knockdown tusk charge.'
        },
        bear: {
            id: 'bear', name: 'Apex War-Bear', subtitle: 'Tamed Grizzly',
            hp: 580, speed: 6.1, dmg: 68, rate: 1.35, range: 2.6, cleave: 2.5,
            color: 0x4c3322, accent: 0xff8a3a,
            treats: [['honey_ham', 3], ['cooked_fish', 2], ['honey', 2], ['raw_fish', 1]],
            need: 3,
            perk: 'Crushing cleave swipe & high-health tank against bosses and hordes.'
        },
        ranger: {
            id: 'ranger', name: 'Haven Vanguard', subtitle: 'Suppressed Scout',
            hp: 300, speed: 6.9, dmg: 34, rate: 0.58, range: 26, ranged: true,
            color: 0x3b4d3e, accent: 0x7ee8fa,
            treats: [], need: 1,
            perk: 'Fires suppressed 5.56 bursts from range without drawing Zone-wide noise.'
        }
    };

    const STANCES = [
        { id: 'follow', label: 'FOLLOW & FIGHT', desc: 'Follows your flank and engages nearby hostiles.' },
        { id: 'stealth', label: 'HEEL / STEALTH', desc: 'Stays close and holds attacks unless you are struck.' },
        { id: 'guard', label: 'GUARD POST', desc: 'Anchors here and defends a 22 m perimeter.' }
    ];

    const HEAL_FOODS = ['cooked_bear', 'cooked_beef', 'cooked_venison', 'cooked_pork', 'cooked_fish', 'cooked_mutton', 'cooked_fowl', 'cooked_rabbit', 'jerky', 'rations', 'canned'];
    const ROMAN = ['I', 'II', 'III', 'IV', 'V'];

    class ZoneCompanions {
        constructor() {
            this.mode = null;
            this.comp = null;
            this.tameMarkers = new Map();
            this.objects = [];
            this.postMarker = null;
            this.pingClock = 10;
        }

        get campaign() { return this.mode?.campaign; }
        get active() { return !!this.comp; }

        start(mode, saved) {
            this.stop();
            this.mode = mode;
            this.installOnce();
            this.placeVanguardPost();
            if (saved?.comp) {
                const c = saved.comp;
                this.spawnCompanion(c.kind, c.pos || { x: BO.Player.pos.x + 2, y: BO.Player.pos.y, z: BO.Player.pos.z + 2 }, c, true);
            }
        }

        stop() {
            this.dismiss(true);
            for (const mk of this.tameMarkers.values()) mk.alive = false;
            this.tameMarkers.clear();
            for (const o of this.objects) o.removeFromParent?.();
            this.objects = [];
            this.postMarker = null;
            this.mode = null;
        }

        snapshot() {
            if (!this.comp) return null;
            const c = this.comp;
            return {
                comp: {
                    kind: c.kind, name: c.name, rank: c.rank, xp: c.xp,
                    hp: Math.round(c.hp), downed: c.downed,
                    stance: c.stance,
                    pos: { x: +c.pos.x.toFixed(2), y: +c.pos.y.toFixed(2), z: +c.pos.z.toFixed(2) },
                    guardPos: c.guardPos ? { ...c.guardPos } : null
                }
            };
        }

        installOnce() {
            if (this._installed) return;
            this._installed = true;
            // Boar Pack Saddle (+12 kg carry limit while Tusk Charger is active).
            const P = BO.SurvivalPack?.prototype;
            const lim = P && Object.getOwnPropertyDescriptor(P, 'limits');
            if (lim?.get) {
                Object.defineProperty(P, 'limits', {
                    configurable: true,
                    get() {
                        const base = lim.get.call(this);
                        const bonus = BO.ZoneCompanions?.carryBonus?.() || 0;
                        return bonus > 0 ? { ...base, weight: base.weight + bonus } : base;
                    }
                });
            }
        }

        carryBonus() {
            const c = this.comp;
            if (!c || c.downed > 0) return 0;
            return ARCHETYPES[c.kind]?.carryBonus || 0;
        }

        placeVanguardPost() {
            const m = this.mode;
            if (!m || m.campaign?.has('sv_no_npcs')) return;
            const haven = BO.Zone?.markers?.find((x) => x.id === 'haven') || { x: -135, z: 142 };
            const x = haven.x - 4.2, z = haven.z + 3.4;
            const y = BO.World.getGroundHeight(x, z, BO.World.terrainHeight(x, z) + 2);
            const g = new THREE.Group();
            const std = (col, ex = {}) => new THREE.MeshStandardMaterial({ color: col, roughness: 0.75, ...ex });
            const add = (w, h, d, col, px, py, pz, ex) => {
                const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), std(col, ex));
                mesh.position.set(px, py, pz);
                g.add(mesh);
                return mesh;
            };
            // Ranger figure + signal banner at Haven
            add(0.48, 0.72, 0.28, 0x3b4d3e, 0, 1.14, 0);
            add(0.28, 0.28, 0.28, 0xd4ad8c, 0, 1.70, 0);
            add(0.32, 0.08, 0.12, 0x7ee8fa, 0, 1.72, 0.11, { emissive: 0x38bdf8, emissiveIntensity: 0.8 });
            add(0.18, 0.78, 0.2, 0x28312b, -0.13, 0.4, 0);
            add(0.18, 0.78, 0.2, 0x28312b, 0.13, 0.4, 0);
            add(0.08, 2.3, 0.08, 0x5c4a38, 0.58, 1.15, 0);
            add(0.46, 0.34, 0.04, 0x8fe3c8, 0.82, 2.05, 0, { emissive: 0x2dd4bf, emissiveIntensity: 0.45 });
            g.position.set(x, y, z);
            m.scene.add(g);
            this.objects.push(g);
            this.postMarker = {
                id: 'comp:vanguard_post', x, y, z,
                name: 'Haven Vanguard Scout',
                label: 'Recruit Haven Vanguard (2 rations, 20× 5.56)',
                alive: true, vanguardPost: true, reach: 2.8
            };
            m.markers.push(this.postMarker);
        }

        buildMesh(kind) {
            const spec = ARCHETYPES[kind];
            const root = new THREE.Group();
            const std = (col, ex = {}) => new THREE.MeshStandardMaterial({ color: col, roughness: 0.72, ...ex });
            const legs = [];
            if (kind === 'ranger') {
                const torso = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.68, 0.26), std(spec.color));
                torso.position.set(0, 1.12, 0);
                const cloak = new THREE.Mesh(new THREE.BoxGeometry(0.52, 0.56, 0.08), std(0x27352a));
                cloak.position.set(0, 1.10, -0.16);
                const head = new THREE.Mesh(new THREE.BoxGeometry(0.27, 0.27, 0.27), std(0xd4ad8c));
                head.position.set(0, 1.66, 0);
                const hood = new THREE.Mesh(new THREE.BoxGeometry(0.31, 0.16, 0.31), std(0x2d3d31));
                hood.position.set(0, 1.76, -0.02);
                const visor = new THREE.Mesh(new THREE.BoxGeometry(0.24, 0.07, 0.06), std(spec.accent, { emissive: spec.accent, emissiveIntensity: 0.9 }));
                visor.position.set(0, 1.66, 0.13);
                const rifle = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.11, 0.72), std(0x262b30, { metalness: 0.65 }));
                rifle.position.set(0.24, 1.12, 0.26);
                const supp = new THREE.Mesh(new THREE.CylinderGeometry(0.022, 0.022, 0.22, 8), std(0x1b1f23, { metalness: 0.8 }));
                supp.rotation.x = Math.PI / 2;
                supp.position.set(0.24, 1.14, 0.68);
                root.add(torso, cloak, head, hood, visor, rifle, supp);
                for (const lx of [-0.12, 0.12]) {
                    const p = new THREE.Group();
                    p.position.set(lx, 0.76, 0);
                    const leg = new THREE.Mesh(new THREE.BoxGeometry(0.16, 0.76, 0.18), std(0x262e28));
                    leg.position.y = -0.38;
                    p.add(leg);
                    root.add(p);
                    legs.push(p);
                }
                return { root, legs, height: 1.85, collar: visor };
            }
            const sz = kind === 'bear' ? 1.48 : kind === 'boar' ? 0.82 : 0.80;
            const legH = 0.42 * sz, bw = 0.40 * sz, bh = 0.36 * sz, bl = 0.92 * sz;
            const by = legH + bh * 0.45;
            const body = new THREE.Mesh(new THREE.BoxGeometry(bw, bh, bl), std(spec.color));
            body.position.set(0, by, 0);
            const head = new THREE.Mesh(new THREE.BoxGeometry(bw * 0.74, bh * 0.74, bw * 0.82), std(spec.color));
            head.position.set(0, by + bh * 0.32, bl * 0.56);
            const snout = new THREE.Mesh(new THREE.BoxGeometry(bw * 0.42, bh * 0.36, bw * 0.50), std(0x2d2520));
            snout.position.set(0, by + bh * 0.22, bl * 0.56 + bw * 0.52);
            // Glowing Resonance collar / harness so you never mistake your companion for a hostile!
            const collar = new THREE.Mesh(
                new THREE.BoxGeometry(bw * 0.86, bh * 0.24, bw * 0.28),
                std(spec.accent, { emissive: spec.accent, emissiveIntensity: 0.95, metalness: 0.4 })
            );
            collar.position.set(0, by + bh * 0.24, bl * 0.36);
            root.add(body, head, snout, collar);
            if (kind === 'wolf') {
                for (const ex of [-1, 1]) {
                    const ear = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.13, 4), std(spec.color));
                    ear.position.set(ex * bw * 0.24, by + bh * 0.78, bl * 0.52);
                    root.add(ear);
                }
                const tail = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.08, 0.34), std(spec.color));
                tail.position.set(0, by + 0.04, -bl * 0.58);
                tail.rotation.x = -0.35;
                root.add(tail);
            } else if (kind === 'boar') {
                for (const tx of [-1, 1]) {
                    const tusk = new THREE.Mesh(new THREE.ConeGeometry(0.032, 0.16, 5), std(0xf4efe2, { metalness: 0.3 }));
                    tusk.position.set(tx * bw * 0.26, by + bh * 0.16, bl * 0.56 + bw * 0.62);
                    tusk.rotation.x = 0.55;
                    root.add(tusk);
                }
                const pack = new THREE.Mesh(new THREE.BoxGeometry(bw * 1.28, bh * 0.55, bl * 0.48), std(0x7c5a38));
                pack.position.set(0, by + bh * 0.22, 0);
                root.add(pack);
            } else if (kind === 'bear') {
                const hump = new THREE.Mesh(new THREE.BoxGeometry(bw * 0.92, bh * 0.35, bl * 0.42), std(spec.color));
                hump.position.set(0, by + bh * 0.52, bl * 0.15);
                root.add(hump);
            }
            for (const [lx, lz] of [[bw * 0.34, bl * 0.34], [-bw * 0.34, bl * 0.34], [bw * 0.34, -bl * 0.34], [-bw * 0.34, -bl * 0.34]]) {
                const pivot = new THREE.Group();
                pivot.position.set(lx, legH, lz);
                const leg = new THREE.Mesh(new THREE.BoxGeometry(0.10 * sz, legH, 0.10 * sz), std(spec.color));
                leg.position.y = -legH / 2;
                pivot.add(leg);
                root.add(pivot);
                legs.push(pivot);
            }
            return { root, legs, height: by + bh * 0.8, collar };
        }

        maxHpOf(kind, rank) {
            const base = ARCHETYPES[kind]?.hp || 240;
            return Math.round(base * (1 + (rank - 1) * 0.22));
        }

        dmgOf(kind, rank) {
            const base = ARCHETYPES[kind]?.dmg || 34;
            return Math.round(base * (1 + (rank - 1) * 0.18));
        }

        spawnCompanion(kind, pos, saved = null, quiet = false) {
            const m = this.mode;
            if (!m || !ARCHETYPES[kind]) return null;
            this.dismiss(true);
            const spec = ARCHETYPES[kind];
            const built = this.buildMesh(kind);
            const rank = BO.Math.clamp(saved?.rank || 1, 1, 5);
            const maxHp = this.maxHpOf(kind, rank);
            const y = BO.World.getGroundHeight(pos.x, pos.z, (pos.y ?? 0) + 2);
            const comp = {
                isCompanion: true, team: 0, alive: true,
                kind, spec,
                name: saved?.name || spec.name,
                rank, xp: saved?.xp || 0,
                maxHp, hp: saved?.hp != null ? Math.min(maxHp, Math.max(1, saved.hp)) : maxHp,
                downed: saved?.downed || 0,
                stance: saved?.stance || 'follow',
                guardPos: saved?.guardPos || null,
                pos: new THREE.Vector3(pos.x, y, pos.z),
                yaw: 0, phase: 0, attackCd: 0,
                root: built.root, legs: built.legs, height: built.height, collar: built.collar,
                getHitboxMeshes: () => []
            };
            comp.root.position.copy(comp.pos);
            m.scene.add(comp.root);
            comp.marker = {
                id: 'comp:active', x: comp.pos.x, y: comp.pos.y, z: comp.pos.z,
                name: comp.name, label: '', alive: true, companionInteract: true, reach: 2.7
            };
            m.markers.push(comp.marker);
            this.comp = comp;
            if (!quiet) {
                BO.FX?.spawnParticles?.(comp.pos.clone().setY(comp.pos.y + 0.9), 18, spec.accent, 3.6, 4, 0.7);
                BO.Sound?.playPerkBuy?.();
                BO.Events.emit('hud:banner', {
                    title: comp.name.toUpperCase() + ' JOINED YOU',
                    sub: spec.perk.toUpperCase() + ' · PRESS ' + BO.Settings.keyLabel(BO.Settings.getKeybinds().survCompanion || 'KeyY') + ' FOR ORDERS',
                    color: '#8fe3c8'
                });
            }
            return comp;
        }

        dismiss(silent = false) {
            if (!this.comp) return;
            const name = this.comp.name;
            this.comp.root.removeFromParent();
            this.comp.root.traverse((o) => { o.geometry?.dispose?.(); o.material?.dispose?.(); });
            if (this.comp.marker) {
                this.comp.marker.alive = false;
                const idx = this.mode?.markers.indexOf(this.comp.marker) ?? -1;
                if (idx >= 0) this.mode.markers.splice(idx, 1);
            }
            this.comp = null;
            if (!silent && this.mode) this.mode.toast(name + ' returned to Haven.');
        }

        onDistressRescued(pos) {
            if (this.comp || !this.mode) return false;
            this.spawnCompanion('ranger', pos);
            this.campaign?.mark('companionsTamed', 1, 80);
            return true;
        }

        cycleStance() {
            const c = this.comp;
            if (!c) {
                this.mode?.toast('No companion yet — tame a wolf, boar or bear in the wild, or recruit a Vanguard at Haven.');
                return false;
            }
            const idx = STANCES.findIndex((s) => s.id === c.stance);
            const next = STANCES[(idx + 1) % STANCES.length];
            c.stance = next.id;
            if (next.id === 'guard') c.guardPos = { x: c.pos.x, y: c.pos.y, z: c.pos.z };
            else c.guardPos = null;
            BO.Sound?.playUIClick?.();
            this.mode?.toast(c.name + ' · ' + next.label + ' — ' + next.desc);
            return true;
        }

        availableTreat(kind) {
            const pts = this.mode?.points || {};
            const spec = ARCHETYPES[kind];
            if (!spec) return null;
            if (this.campaign?.has('sv_free_craft')) return spec.treats[0] || ['bone', 2];
            for (const [itemId, val] of spec.treats) {
                if ((pts[itemId] || 0) > 0) return [itemId, val];
            }
            return null;
        }

        activate(marker) {
            const m = this.mode;
            if (!m || !marker) return false;
            if (marker.vanguardPost) {
                if (this.comp?.kind === 'ranger') {
                    m.toast('Your Haven Vanguard is already with you.');
                    return true;
                }
                if (!m.spend({ rations: 2, ammo556: 20 })) {
                    m.toast('Recruiting a Haven Vanguard requires 2 field rations and 20× 5.56 rounds.');
                    return true;
                }
                this.spawnCompanion('ranger', { x: marker.x + 1.2, y: marker.y, z: marker.z + 1.2 });
                this.campaign?.mark('companionsTamed', 1, 80);
                return true;
            }
            if (marker.tameAnimal) {
                const a = marker.tameAnimal;
                if (!a.alive) return true;
                const spec = ARCHETYPES[a.kind];
                const treat = this.availableTreat(a.kind);
                if (!treat) {
                    const names = spec.treats.slice(0, 3).map(([k]) => BO.SurvivalItemName(k)).join(', ');
                    m.toast('Carry ' + names + ' to tame this ' + a.spec.name.toLowerCase() + '.');
                    return true;
                }
                const [itemId, val] = treat;
                if (!this.campaign?.has('sv_free_craft')) m.points[itemId]--;
                a.tameProgress = (a.tameProgress || 0) + val;
                a.tameCalmed = m.clock + 15;
                a.state = 'wander';
                a.goal = null;
                BO.FX?.spawnParticles?.(a.pos.clone().setY(a.pos.y + a.height * 0.8), 10, spec.accent, 2.2, 3, 0.5);
                if (a.tameProgress >= spec.need) {
                    const spawnPos = { x: a.pos.x, y: a.pos.y, z: a.pos.z };
                    a.alive = false;
                    a.deathTimer = 0;
                    a.destroy();
                    const list = BO.ZoneWild?.animals;
                    const idx = list ? list.indexOf(a) : -1;
                    if (idx >= 0) list.splice(idx, 1);
                    const mk = this.tameMarkers.get(a.id);
                    if (mk) { mk.alive = false; this.tameMarkers.delete(a.id); }
                    this.spawnCompanion(a.kind, spawnPos);
                    this.campaign?.mark('companionsTamed', 1, 80);
                    m.refreshTargets();
                } else {
                    m.toast(a.spec.name + ' accepted ' + BO.SurvivalItemName(itemId) + ' (' + a.tameProgress + '/' + spec.need + ' — feed once more!).');
                }
                return true;
            }
            if (marker.companionInteract && this.comp) {
                const c = this.comp;
                if (c.downed > 0) {
                    if (m.spend({ bandage: 1 }) || m.spend({ medkits: 1 })) {
                        c.downed = 0;
                        c.hp = Math.round(c.maxHp * 0.75);
                        c.root.rotation.z = 0;
                        BO.FX?.spawnParticles?.(c.pos.clone().setY(c.pos.y + 0.8), 12, 0x8fe3c8, 2.5, 4, 0.5);
                        m.toast(c.name + ' is back on their feet!');
                    } else {
                        m.toast('Need 1 bandage or medkit to revive immediately (' + Math.ceil(c.downed) + ' s left).');
                    }
                    return true;
                }
                if (c.hp < c.maxHp) {
                    const food = HEAL_FOODS.find((id) => (m.points[id] || 0) > 0);
                    if (food && m.spend({ [food]: 1 })) {
                        const heal = Math.round(c.maxHp * 0.55);
                        c.hp = Math.min(c.maxHp, c.hp + heal);
                        this.grantXp(20);
                        BO.FX?.spawnParticles?.(c.pos.clone().setY(c.pos.y + 0.8), 10, 0x8fe3c8, 2.2, 4, 0.45);
                        m.toast('Fed ' + BO.SurvivalItemName(food) + ' to ' + c.name + ' (+' + heal + ' HP).');
                        return true;
                    }
                }
                m.composure = Math.min(100, (m.composure || 80) + 8);
                BO.FX?.spawnParticles?.(c.pos.clone().setY(c.pos.y + c.height), 8, c.spec.accent, 1.8, 2, 0.45);
                m.toast(c.kind === 'ranger' ? c.name + ': "Perimeter clear. Ready when you are."' : c.name + ' leans into your hand (+8 composure).');
                return true;
            }
            return false;
        }

        grantXp(amount) {
            const c = this.comp;
            if (!c || c.rank >= 5) return;
            c.xp += amount;
            const need = c.rank * 90;
            if (c.xp >= need) {
                c.xp -= need;
                c.rank++;
                c.maxHp = this.maxHpOf(c.kind, c.rank);
                c.hp = c.maxHp;
                BO.FX?.spawnParticles?.(c.pos.clone().setY(c.pos.y + 1.0), 16, 0xf2d07a, 3.2, 4, 0.65);
                this.mode?.toast(c.name + ' reached Rank ' + ROMAN[c.rank - 1] + ' (' + c.maxHp + ' HP, ' + this.dmgOf(c.kind, c.rank) + ' DMG)!');
            }
        }

        damageCompanion(amount) {
            const c = this.comp;
            if (!c || c.downed > 0) return;
            if (this.campaign?.has('sv_god_mode')) return;
            c.hp -= amount * 0.65;
            BO.FX?.spawnParticles?.(c.pos.clone().setY(c.pos.y + 0.7), 5, 0x991b1b, 2.2, 6, 0.35);
            if (c.hp <= 0) {
                c.hp = 0;
                c.downed = 22;
                c.root.rotation.z = Math.PI / 2;
                this.mode?.toast(c.name + ' is downed! Use a bandage to revive or wait 22 s.');
            }
        }

        /** Lets nearby infected fight an active, non-downed companion when closer than the player. */
        targetForZombie(z) {
            const c = this.comp;
            if (!c || c.downed > 0 || c.stance === 'stealth') return null;
            const dz = c.pos.distanceTo(z.pos);
            if (dz > 9.5) return null;
            const dp = BO.Player.pos.distanceTo(z.pos);
            if (dz < dp - 1.5) return { x: c.pos.x, y: c.pos.y, z: c.pos.z, companion: c, attackRange: 1.75, forceDirect: true };
            return null;
        }

        updateTamePrompts(p) {
            const m = this.mode;
            const wild = BO.ZoneWild?.animals || [];
            const seen = new Set();
            for (const a of wild) {
                if (!a.alive || !ARCHETYPES[a.kind]) continue;
                if (a.tameCalmed > m.clock && a.state === 'attack') a.state = 'wander';
                const d = a.pos.distanceTo(p.pos);
                if (d > 8.5) continue;
                seen.add(a.id);
                let mk = this.tameMarkers.get(a.id);
                if (!mk) {
                    mk = { id: 'tame:' + a.id, x: a.pos.x, y: a.pos.y, z: a.pos.z, name: a.spec.name, label: '', alive: true, tameAnimal: a, reach: 4.3 };
                    this.tameMarkers.set(a.id, mk);
                    m.markers.push(mk);
                }
                mk.x = a.pos.x; mk.y = a.pos.y; mk.z = a.pos.z; mk.alive = true;
                const spec = ARCHETYPES[a.kind];
                const treat = this.availableTreat(a.kind);
                const prog = a.tameProgress ? ` (${a.tameProgress}/${spec.need})` : '';
                mk.label = treat
                    ? `Offer ${BO.SurvivalItemName(treat[0])} to tame ${a.spec.name}${prog}`
                    : `Tame ${a.spec.name} (needs ${BO.SurvivalItemName(spec.treats[3]?.[0] || spec.treats[0][0])})`;
            }
            for (const [id, mk] of this.tameMarkers) {
                if (!seen.has(id)) {
                    mk.alive = false;
                    const idx = m.markers.indexOf(mk);
                    if (idx >= 0) m.markers.splice(idx, 1);
                    this.tameMarkers.delete(id);
                }
            }
            if (this.postMarker) {
                this.postMarker.label = this.comp?.kind === 'ranger'
                    ? 'Haven Vanguard active'
                    : 'Recruit Haven Vanguard (2 rations, 20× 5.56)';
            }
        }

        update(dt) {
            const m = this.mode;
            if (!m || !m.active) return;
            const p = BO.Player;
            this.updateTamePrompts(p);
            const c = this.comp;
            if (!c) return;

            // Update interaction marker on the companion
            if (c.marker) {
                c.marker.x = c.pos.x; c.marker.y = c.pos.y; c.marker.z = c.pos.z;
                c.marker.alive = Math.hypot(c.pos.x - p.pos.x, c.pos.z - p.pos.z) < 6;
                if (c.downed > 0) c.marker.label = `Revive ${c.name} (bandage · ${Math.ceil(c.downed)}s)`;
                else if (c.hp < c.maxHp) c.marker.label = `Feed ${c.name} (${Math.ceil(c.hp)}/${c.maxHp} HP)`;
                else c.marker.label = c.kind === 'ranger' ? `Check in with ${c.name} (Rank ${ROMAN[c.rank - 1]})` : `Pet ${c.name} (Rank ${ROMAN[c.rank - 1]})`;
            }

            if (c.downed > 0) {
                c.downed -= dt;
                if (c.downed <= 0) {
                    c.downed = 0;
                    c.hp = Math.round(c.maxHp * 0.55);
                    c.root.rotation.z = 0;
                    m.toast(c.name + ' recovered!');
                }
                return;
            }

            // Passive out-of-combat regen
            if (c.hp < c.maxHp) c.hp = Math.min(c.maxHp, c.hp + dt * 2.5);

            // Teleport leash when following (including across Dungeon / Arena / Fast-Travel jumps!)
            const anchor = c.stance === 'guard' && c.guardPos ? c.guardPos : p.pos;
            const distAnchor = Math.hypot(c.pos.x - anchor.x, c.pos.z - anchor.z);
            if (c.stance !== 'guard' && (distAnchor > 50 || Math.abs(c.pos.y - p.pos.y) > 18)) {
                const fwd = p.getMoveDirectionVectors().right;
                const tx = p.pos.x + fwd.x * 2.2, tz = p.pos.z + fwd.z * 2.2;
                const inSealed = !!(BO.ZoneDungeons?.inside || BO.ZoneLegends?.arena);
                c.pos.set(tx, inSealed ? p.pos.y : BO.World.getGroundHeight(tx, tz, p.pos.y + 2), tz);
                c.root.position.copy(c.pos);
            }

            // Zone Hound Tracker's Nose: ping nearby unsearched high-value container or bag
            if (c.kind === 'wolf' && c.stance !== 'stealth') {
                this.pingClock -= dt;
                if (this.pingClock <= 0) {
                    this.pingClock = 18;
                    const cont = m.loot?.list?.find((e) => !m.loot.searched.has(e.i) && (e.story || e.tier >= 2 || /gun_locker|military_crate|lab_cabinet/.test(e.type)) && Math.hypot(e.x - p.pos.x, e.z - p.pos.z) < 42);
                    if (cont) {
                        BO.FX?.spawnParticles?.(new THREE.Vector3(cont.x, cont.y + 1.2, cont.z), 12, 0x8fe3c8, 2.2, 1, 0.85);
                        m.toast('Zone Hound caught a scent — ' + (cont.marker?.name || 'cache') + ' ' + Math.round(Math.hypot(cont.x - p.pos.x, cont.z - p.pos.z)) + ' m away!');
                    }
                }
            }

            // Acquire hostile target
            c.attackCd = Math.max(0, c.attackCd - dt);
            const aggroRange = c.stance === 'stealth' ? 4.2 : c.stance === 'guard' ? 22 : 24;
            let best = null, bestD = aggroRange;
            for (const pool of [m.zombies, m.bots]) {
                for (let i = 0; i < pool.length; i++) {
                    const u = pool[i];
                    if (!u.alive || u.team === 0) continue;
                    const da = Math.hypot(u.pos.x - anchor.x, u.pos.z - anchor.z);
                    if (da > aggroRange) continue;
                    const dc = Math.hypot(u.pos.x - c.pos.x, u.pos.z - c.pos.z);
                    if (dc < bestD) { bestD = dc; best = u; }
                }
            }

            const spec = c.spec;
            let moveX = null, moveZ = null, spd = 0;
            if (best) {
                const dx = best.pos.x - c.pos.x, dz = best.pos.z - c.pos.z;
                const d = Math.hypot(dx, dz);
                if (spec.ranged) {
                    const los = BO.World.hasLineOfSight(c.pos.x, c.pos.y + 1.35, c.pos.z, best.pos.x, best.pos.y + 0.95, best.pos.z);
                    if (d <= spec.range && los) {
                        c.yaw = Math.atan2(dx, dz);
                        if (c.attackCd <= 0) {
                            c.attackCd = spec.rate;
                            const dmg = this.dmgOf(c.kind, c.rank);
                            BO.FX?.spawnTracer?.(c.pos.clone().setY(c.pos.y + 1.25), best.pos.clone().setY(best.pos.y + 0.95), 0x7ee8fa, 0.022, 0.07);
                            const killed = m.hit(best, dmg, 'torso', null, 'bullet', c);
                            this.grantXp(killed ? 18 : 4);
                        }
                    } else {
                        moveX = best.pos.x; moveZ = best.pos.z; spd = spec.speed;
                    }
                } else if (d <= spec.range + (best.radius || 0.45)) {
                    c.yaw = Math.atan2(dx, dz);
                    if (c.attackCd <= 0) {
                        c.attackCd = spec.rate;
                        const dmg = this.dmgOf(c.kind, c.rank);
                        const killed = m.hit(best, dmg, 'torso', null, 'melee', c);
                        if (spec.stun && best.alive) best.stunTimer = Math.max(best.stunTimer || 0, spec.stun);
                        if (spec.cleave) {
                            for (const z2 of m.zombies) {
                                if (z2 !== best && z2.alive && z2.pos.distanceTo(best.pos) <= spec.cleave) {
                                    m.hit(z2, Math.round(dmg * 0.65), 'torso', null, 'melee', c);
                                }
                            }
                        }
                        BO.FX?.spawnParticles?.(best.pos.clone().setY(best.pos.y + 0.9), 7, spec.accent, 2.8, 6, 0.35);
                        BO.Sound?.playMeleeHit?.();
                        this.grantXp(killed ? 22 : 5);
                    }
                } else {
                    moveX = best.pos.x; moveZ = best.pos.z; spd = spec.speed;
                }
            } else {
                const right = p.getMoveDirectionVectors().right;
                const goalX = c.stance === 'guard' && c.guardPos ? c.guardPos.x : p.pos.x + right.x * 2.4;
                const goalZ = c.stance === 'guard' && c.guardPos ? c.guardPos.z : p.pos.z + right.z * 2.4;
                const gd = Math.hypot(goalX - c.pos.x, goalZ - c.pos.z);
                if (gd > 1.6) {
                    moveX = goalX; moveZ = goalZ;
                    spd = gd > 7 ? spec.speed * 1.12 : spec.speed * 0.72;
                }
            }

            if (moveX !== null && spd > 0) {
                const want = Math.atan2(moveX - c.pos.x, moveZ - c.pos.z);
                let diff = ((want - c.yaw + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
                c.yaw += BO.Math.clamp(diff, -8 * dt, 8 * dt);
                const nx = c.pos.x + Math.sin(c.yaw) * spd * dt;
                const nz = c.pos.z + Math.cos(c.yaw) * spd * dt;
                const inSealed = !!(BO.ZoneDungeons?.inside || BO.ZoneLegends?.arena);
                if (inSealed) {
                    const tryPos = new THREE.Vector3(nx, c.pos.y, nz);
                    BO.World.resolveHorizontal?.(tryPos, 0.42, 1.4, false);
                    c.pos.x = tryPos.x; c.pos.z = tryPos.z;
                    c.pos.y = BO.World.getGroundHeight(c.pos.x, c.pos.z, p.pos.y + 1.5);
                } else if (!BO.Zone.inReservoir(nx, nz)) {
                    c.pos.x = nx; c.pos.z = nz;
                    c.pos.y = BO.World.getGroundHeight(nx, nz, c.pos.y + 1.6);
                }
                c.phase += dt * spd * 3.2;
            }
            const swing = spd > 0 ? Math.sin(c.phase) * Math.min(0.65, spd * 0.1) : 0;
            c.legs.forEach((l, i) => { l.rotation.x = (i % 2 === 0 ? swing : -swing); });
            c.root.position.copy(c.pos);
            c.root.rotation.y = c.yaw;
        }

        hudChip() {
            const c = this.comp;
            if (!c) return '';
            const st = c.downed > 0 ? 'DOWNED ' + Math.ceil(c.downed) + 's' : c.stance.toUpperCase();
            return `${c.name} ${ROMAN[c.rank - 1]} · ${Math.ceil(c.hp)}/${c.maxHp} · ${st}`;
        }
    }

    BO.ZoneCompanions = new ZoneCompanions();
    BO.ZoneCompanions.ARCHETYPES = ARCHETYPES;
    BO.ZoneCompanions.STANCES = STANCES;
})(window.BO);
;

/* --- src/systems/ZoneArmory.js --- */
/* ============================================================================
   BLACKOUT OPS — Zone Armory, Obsidian Tier & Homestead Automation (BO.ZoneArmory)
   · 3D Workbench Gunsmithing: craft & mount real 3D Optics, Suppressors,
     Muzzle Brakes, Foregrips, Lasers, Extended/Drum Mags, Stocks & Camos
     onto any Survival weapon with instant 3D viewmodel rebuild.
   · Resonance Anvil: temper weapon rarity all the way to Legendary, reroll
     traits, and socket Elemental Cores (Obsidian, Cryo, Arc, Solar).
   · Obsidian Tier & Homestead Buildables:
     - obsidian_armor (+140 armor, 180 max armor), obsidian_blade (Reaper Scythe)
     - obsidianWall (1,400 HP blast-proof structural wall)
     - armoryBench (Gunsmith & Anvil bench)
     - planter (buildable crop plot anywhere at your base)
     - rainbarrel (passively collects filtered water; 3× faster in rain)
     - waystone (Resonance Waystone — fast-travel & respawn directly at your base!)
============================================================================ */
(function (BO) {
    'use strict';

    const F = BO.SurvivalFrontierData;
    const CD = BO.SurvivalCampaignData;

    Object.assign(F.items, {
        obsidian_armor: ['Obsidian trauma rig', 'Equipment', 2.4],
        optic_kit: ['Precision optic kit', 'Components', 0.35],
        suppressor_kit: ['Baffled suppressor kit', 'Components', 0.42],
        mag_kit: ['Extended feed kit', 'Components', 0.38]
    });

    F.recipes.push(
        { id: 'obsidianArmor', name: 'Obsidian trauma rig', station: 'bench', cat: 'gear', cost: { obsidian: 4, ingot: 3, leather: 3 }, gain: { obsidian_armor: 1 }, desc: 'Volcanic glass & steel plate carrier: raises max armour to 180 and restores +140 armour.' },
        { id: 'makeOpticKit', name: 'Precision optic kit', station: 'bench', cat: 'weapons', cost: { lens: 1, scrap: 2, wire: 1 }, gain: { optic_kit: 1 }, desc: 'Ground quartz reticle & rail mount for fitting rifle scopes and sights in Gunsmith.' },
        { id: 'makeSuppressorKit', name: 'Baffled suppressor kit', station: 'bench', cat: 'weapons', cost: { ingot: 1, scrap: 2, cloth: 2 }, gain: { suppressor_kit: 1 }, desc: 'Machined baffle stack for mounting suppressors and compensators in Gunsmith.' },
        { id: 'makeMagKit', name: 'Extended feed kit', station: 'bench', cat: 'weapons', cost: { ingot: 1, scrap: 2, wire: 1 }, gain: { mag_kit: 1 }, desc: 'High-tension follower springs, grips and stocks for Gunsmith customization.' },
        { id: 'forgeObsidianScythe', name: 'Forge: Obsidian Reaper', station: 'kiln', cat: 'weapons', cost: { obsidian: 6, ingot: 3, gold: 1, leather: 2 }, gain: {}, desc: 'Forges a Legendary Obsidian-cored Reaper Scythe and equips it.', obsidianWeapon: 'reaper_scythe' }
    );

    if (BO.SurvivalHotbar?.usable) BO.SurvivalHotbar.usable.add('obsidian_armor');

    CD.build.push(
        { id: 'obsidianWall', name: 'Obsidian blast wall', size: [2.8, 2.75, 0.34], cost: { obsidian: 3, brick: 3, ingot: 1 }, color: 0x281e36, detail: '1,400 HP volcanic-glass & masonry fortress wall. Nearly impervious to horde breaches.' },
        { id: 'armoryBench', name: 'Armory & Gunsmith anvil', size: [1.55, 1.0, 0.85], cost: { ingot: 3, planks: 4, scrap: 4 }, color: 0x3b424a, detail: 'Counts as a workbench and opens the 3D Gunsmith & Resonance Anvil to fit scopes, suppressors, camos and cores.' },
        { id: 'planter', name: 'Homestead crop planter', size: [1.44, 0.25, 1.24], cost: { planks: 3, clay: 2, bonemeal: 1 }, color: 0x6b533b, detail: 'A raised garden plot you can build anywhere at your base. Plant seeds, water, fertilise with bone meal and harvest.' },
        { id: 'rainbarrel', name: 'Rainwater collector', size: [0.85, 1.12, 0.85], cost: { planks: 3, ingot: 1, cloth: 1 }, color: 0x456272, detail: 'Passively filters up to 3 fresh water (fills 3× faster during rain). Interact to draw water.' },
        { id: 'waystone', name: 'Resonance waystone', size: [0.95, 2.15, 0.95], cost: { obsidian: 2, quartz: 3, aetherShard: 1, stone: 4 }, color: 0x3a2d54, detail: 'Attunes your base to the Zone network: unlocks direct Fast Travel and Respawn right at your homestead.' }
    );

    const CORES = {
        obsidian: { id: 'obsidian', name: 'Obsidian Razor Core', color: '#c084fc', hex: 0xa855f7, cost: { obsidian: 3, ingot: 1 }, desc: '+16% weapon damage; hits lacerate targets for bonus bleed damage.' },
        cryo: { id: 'cryo', name: 'Cryo Frost Core', color: '#7ee8fa', hex: 0x38bdf8, cost: { quartz: 3, freshWater: 2 }, desc: '+10% weapon damage; 35% chance to chill & slow infected on hit.' },
        arc: { id: 'arc', name: 'Arc Volt Core', color: '#fde047', hex: 0xfacc15, cost: { battery: 2, wire: 2 }, desc: '+10% weapon damage; 30% chance to arc chain lightning to nearby hostiles.' },
        solar: { id: 'solar', name: 'Solar Napalm Core', color: '#fb923c', hex: 0xf97316, cost: { powder: 3, fat: 2 }, desc: '+10% weapon damage; ignites targets for searing fire damage over time.' }
    };

    const RARITY_LADDER = ['common', 'uncommon', 'rare', 'epic', 'legendary'];
    const TEMPER_COST = {
        uncommon: { scrap: 4, ingot: 1 },
        rare: { ingot: 3, quartz: 2 },
        epic: { ingot: 4, gold: 2, aetherShard: 1 },
        legendary: { obsidian: 3, gold: 2, aetherShard: 2 }
    };

    const SLOT_COST = {
        optic: { optic_kit: 1 },
        muzzle: { suppressor_kit: 1 },
        underbarrel: { mag_kit: 1 },
        magazine: { mag_kit: 1 },
        stock: { mag_kit: 1 }
    };

    const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

    class ZoneArmory {
        constructor() {
            this.mode = null;
            this.uiOpen = null;
            this.el = null;
            this.barrels = new Map();
        }

        get campaign() { return this.mode?.campaign; }

        start(mode, saved) {
            this.stop();
            this.mode = mode;
            this.installOnce();
            if (saved?.barrels) {
                for (const [id, st] of saved.barrels) this.barrels.set(String(id), { stored: st.stored || 0, progress: st.progress || 0 });
            }
            // Register any restored planters, rainbarrels, waystones
            for (const p of mode.campaign?.placed || []) {
                if (p.alive) this.onPiecePlaced(p, true);
            }
            // Ensure restored weapons preserve attachments & cores
            for (const w of BO.Player.weapons || []) this.recomputeWeapon(w, false);
            BO.Player.rebuildViewmodel?.();
        }

        stop() {
            this.close(true);
            this.barrels.clear();
            this.mode = null;
        }

        snapshot() {
            return {
                barrels: [...this.barrels.entries()].map(([id, b]) => [id, { stored: b.stored, progress: +b.progress.toFixed(1) }])
            };
        }

        installOnce() {
            if (this._installed) return;
            this._installed = true;
            const self = this;
            const C = BO.SurvivalCampaign.prototype;

            // Armory bench counts as a workbench
            const stAvail = C.stationAvailable;
            C.stationAvailable = function (type) {
                if (stAvail.call(this, type)) return true;
                if (type === 'bench') return stAvail.call(this, 'armoryBench');
                return false;
            };

            // Decorate & register new buildables when placed
            const place = C.place;
            C.place = function (piece) {
                place.call(this, piece);
                if (piece.alive) self.onPiecePlaced(piece, false);
            };

            // Dismantling cleans up custom plots / barrels / waystone markers
            const D = BO.SurvivalDeepSystems?.prototype;
            if (D?.dismantleNearest) {
                const dism = D.dismantleNearest;
                D.dismantleNearest = function () {
                    const before = this.campaign.placed.filter((x) => x.alive);
                    const res = dism.call(this);
                    for (const p of before) if (!p.alive) self.onPieceRemoved(p);
                    return res;
                };
            }

            // Waystones add fast-travel & respawn points!
            const O = BO.SurvivalObjectives.prototype;
            const tp = O.travelPoints;
            O.travelPoints = function () {
                const list = tp.call(this);
                let n = 1;
                for (const p of this.campaign.placed) {
                    if (p.alive && p.type === 'waystone') {
                        list.push({ id: 'waystone:' + p.id, name: 'Homestead Waystone' + (n > 1 ? ' #' + n : ''), x: p.x + 1.4, y: p.y, z: p.z + 1.4, kind: 'Waystone' });
                        n++;
                    }
                }
                return list;
            };
            const rp = C.respawnPoint;
            C.respawnPoint = function () {
                const ws = this.placed.find((p) => p.alive && p.type === 'waystone');
                if (ws && (!this.placed.some((p) => p.alive && p.type === 'bed'))) {
                    return { x: ws.x + 1.2, y: BO.World.getGroundHeight(ws.x + 1.2, ws.z, 80), z: ws.z, name: 'your Resonance Waystone' };
                }
                return rp.call(this);
            };

            // Obsidian Reaper forge recipe hook
            const P = BO.SurvivalPack.prototype;
            const craft = P.craft;
            P.craft = function (id) {
                const ok = craft.call(this, id);
                const rec = ok && this.recipe(id);
                if (rec?.obsidianWeapon && self.mode) {
                    const slot = BO.Player.activeSlot >= 0 ? BO.Player.activeSlot : (BO.Player.weapons.length < 2 ? -1 : 0);
                    const roll = { rarity: 'legendary', perks: ['vampiric', 'lightweight', 'durable'], title: 'Crater\'s Edge' };
                    const w = self.mode.loot.give(rec.obsidianWeapon, 100, slot, roll);
                    if (w) { w.cfg.survCore = 'obsidian'; self.recomputeWeapon(w, true); }
                    this.campaign.mark('obsidianForged', 1, 100);
                }
                if (ok && id === 'obsidianArmor') this.campaign.mark('obsidianForged', 1, 60);
                return ok;
            };

            // Elemental Core proc on hit! SurvivalMode.hit(entity, amount, hitbox, dir, damageKind, agent)
            const M = BO.SurvivalMode;
            const hit = M.hit.bind(M);
            M.hit = function (entity, amount, hitbox, dir, damageKind, agent = null) {
                const w = !agent ? BO.Player.activeWeapon : null;
                const core = (damageKind === 'bullet' || (damageKind === 'melee' && w?.stats?.kind === 'melee')) ? w?.cfg?.survCore : null;
                if (core && entity?.alive && entity.team !== 0) {
                    const pt = entity.pos?.clone()?.setY((entity.pos.y || 0) + 1.0);
                    if (core === 'obsidian') {
                        amount *= 1.12;
                        if (pt) BO.FX?.spawnParticles?.(pt, 5, 0xa855f7, 3.0, 5, 0.35);
                    } else if (core === 'cryo' && Math.random() < 0.38) {
                        entity.frozenTimer = Math.max(entity.frozenTimer || 0, 2.4);
                        entity.stunTimer = Math.max(entity.stunTimer || 0, 0.65);
                        if (pt) BO.FX?.spawnParticles?.(pt, 6, 0x38bdf8, 2.8, 3, 0.4);
                    } else if (core === 'solar' && Math.random() < 0.45) {
                        entity.burnTimer = Math.max(entity.burnTimer || 0, 4.0);
                        amount *= 1.08;
                        if (pt) BO.FX?.spawnParticles?.(pt, 6, 0xf97316, 3.2, 4, 0.4);
                    } else if (core === 'arc' && Math.random() < 0.32 && !this._arcChain) {
                        this._arcChain = true;
                        for (const z2 of this.zombies) {
                            if (z2 !== entity && z2.alive && z2.pos.distanceTo(entity.pos) < 5.5) {
                                if (pt) BO.FX?.spawnTracer?.(pt, z2.pos.clone().setY(z2.pos.y + 0.95), 0xfacc15, 0.03, 0.12);
                                hit(z2, Math.round(amount * 0.55), 'torso', null, 'bullet', null);
                                break;
                            }
                        }
                        this._arcChain = false;
                    }
                }
                return hit(entity, amount, hitbox, dir, damageKind, agent);
            };
        }

        onPiecePlaced(piece, restored = false) {
            const m = this.mode;
            if (!m) return;
            const { x, y, z, type } = piece;
            const extras = (piece._armoryMeshes = piece._armoryMeshes || []);
            const addM = (geo, col, px, py, pz, opt = {}) => {
                const mesh = m.mesh(geo, col, px, py, pz, opt);
                extras.push(mesh);
                return mesh;
            };
            if (type === 'obsidianWall') {
                if (!piece.part) {
                    const [w, h, d] = piece.size;
                    const part = m.addStructure(piece.mesh, w, h, d, 'brick');
                    part.hp = part.maxHp = Number.isFinite(piece.hp) ? piece.hp : 1400;
                    part.buildPiece = piece;
                    piece.part = part;
                } else {
                    piece.part.maxHp = 1400;
                    if (!Number.isFinite(piece.hp)) piece.part.hp = 1400;
                }
                if (piece.mesh?.material) {
                    piece.mesh.material.metalness = 0.55;
                    piece.mesh.material.roughness = 0.28;
                    piece.mesh.material.emissive = new THREE.Color(0x3b1d6e);
                    piece.mesh.material.emissiveIntensity = 0.22;
                }
            } else if (type === 'armoryBench') {
                addM(new THREE.BoxGeometry(0.45, 0.28, 0.32), 0x22262b, x - 0.38, y + 1.14, z, { metalness: 0.85, roughness: 0.3 });
                addM(new THREE.BoxGeometry(0.65, 0.08, 0.18), 0x8fe3c8, x + 0.28, y + 1.05, z - 0.15, { emissive: 0x2dd4bf, emissiveIntensity: 0.6 });
                m.markers.push({ ...piece, id: 'build:' + piece.id, name: 'Armory & Gunsmith Anvil', label: 'Open Gunsmith & Resonance Anvil', alive: true, armoryStation: true });
            } else if (type === 'planter') {
                if (piece.mesh) piece.mesh.visible = false; // SurvivalActivities renders rim, soil & growing crop shoots
                m.campaign?.activities?.addCustomPlot?.(piece);
            } else if (type === 'rainbarrel') {
                if (piece.mesh) piece.mesh.visible = false;
                addM(new THREE.CylinderGeometry(0.42, 0.38, 1.08, 12), 0x3d5c6c, x, y + 0.54, z, { roughness: 0.6, metalness: 0.25 });
                const water = addM(new THREE.CircleGeometry(0.37, 12), 0x56b4d3, x, y + 1.09, z, { emissive: 0x0284c7, emissiveIntensity: 0.35 });
                water.rotation.x = -Math.PI / 2;
                if (!this.barrels.has(String(piece.id))) this.barrels.set(String(piece.id), { stored: restored ? 1 : 0, progress: 0 });
                const mk = { ...piece, id: 'build:' + piece.id, name: 'Rainwater collector', label: 'Rainwater collector (filling…)', alive: true, rainBarrel: String(piece.id) };
                piece._armoryMarker = mk;
                m.markers.push(mk);
            } else if (type === 'waystone') {
                if (piece.mesh) piece.mesh.visible = false;
                addM(new THREE.BoxGeometry(0.95, 0.28, 0.95), 0x3e3a46, x, y + 0.14, z);
                const spire = addM(new THREE.OctahedronGeometry(0.42), 0x8fe3c8, x, y + 1.38, z, { emissive: 0x6d28d9, emissiveIntensity: 0.95, metalness: 0.5 });
                spire.scale.set(0.85, 2.2, 0.85);
                m.campaign?.pack?.addLight?.('ws:' + piece.id, { x, y: y + 0.5, z });
                const mk = { ...piece, id: 'build:' + piece.id, name: 'Resonance Waystone', label: 'Use Resonance Waystone (Fast Travel)', alive: true, waystone: true };
                piece._armoryMarker = mk;
                m.markers.push(mk);
                if (!restored) m.campaign?.mark('waystonesBuilt', 1, 75);
            }
        }

        onPieceRemoved(piece) {
            if (!piece || !this.mode) return;
            for (const mesh of piece._armoryMeshes || []) this.mode.disposeOwned(mesh);
            piece._armoryMeshes = [];
            if (piece.type === 'planter') this.campaign?.activities?.removeCustomPlot?.(piece.id);
            if (piece.type === 'rainbarrel') this.barrels.delete(String(piece.id));
            if (piece._armoryMarker) piece._armoryMarker.alive = false;
        }

        activate(marker) {
            const m = this.mode;
            if (!m || !marker) return false;
            if (marker.armoryStation) {
                this.open(BO.Player.activeSlot >= 0 ? BO.Player.activeSlot : 0);
                return true;
            }
            if (marker.waystone) {
                BO.SurvivalUI.show('map');
                return true;
            }
            if (marker.rainBarrel !== undefined) {
                const st = this.barrels.get(marker.rainBarrel);
                if (!st || st.stored < 1) {
                    m.toast('Rainwater collector is still filtering water (' + Math.floor((st?.progress || 0) / 45 * 100) + '%).');
                    return true;
                }
                if (this.campaign.pack.room('freshWater', 1) < 1) {
                    m.toast('Backpack is too full for filtered water.');
                    return true;
                }
                const take = st.stored;
                st.stored = 0;
                m.grant({ freshWater: take });
                this.campaign.mark('waterDrawn', take, 3);
                return true;
            }
            return false;
        }

        update(dt) {
            const m = this.mode;
            if (!m || !m.active) return;
            const raining = /rain|storm|blizzard/i.test(m.localWeather || m.weather || '');
            const rate = (raining ? 3.0 : 1.0) * (this.campaign?.has('sv_no_cooldowns') ? 25 : 1);
            for (const p of this.campaign?.placed || []) {
                if (!p.alive || p.type !== 'rainbarrel') continue;
                const st = this.barrels.get(String(p.id));
                if (!st) continue;
                if (st.stored < 3) {
                    st.progress += dt * rate;
                    if (st.progress >= 45) {
                        st.progress = 0;
                        st.stored++;
                    }
                }
                if (p._armoryMarker) {
                    p._armoryMarker.label = st.stored > 0
                        ? `Draw filtered water (${st.stored}/3 ready)`
                        : `Rainwater collector · ${Math.min(99, Math.floor(st.progress / 45 * 100))}%${raining ? ' (rain ×3)' : ''}`;
                }
            }
        }

        /* ------------------------------------------------------------ Weapon Refit & Gunsmith UI */
        recomputeWeapon(w, rebuildVm = true) {
            if (!w || !w.cfg) return w;
            const P = BO.Player;
            w._fit = null;
            w.stats = BO.Loadout.computeWeaponStats(w.cfg, w.papTier || 0, P.mpPerks || [], !!w.isDualWield);
            const mk = w.survivalMk || 1;
            if (mk >= 2 && w.stats.kind !== 'melee') {
                w.stats.damage = Math.round(w.stats.damage * 1.24);
                w.stats.magSize = Math.ceil(w.stats.magSize * 1.20);
                w.stats.reloadTime = Number((w.stats.reloadTime * 0.88).toFixed(2));
            }
            if (mk >= 3 && w.stats.kind !== 'melee') {
                w.stats.damage = Math.round(w.stats.damage * 1.19);
                w.stats.magSize = Math.ceil(w.stats.magSize * 1.16);
                w.stats.reloadTime = Number((w.stats.reloadTime * 0.88).toFixed(2));
            }
            if (w.cfg.survCore && CORES[w.cfg.survCore]) {
                w.stats.damage = Math.round(w.stats.damage * (w.cfg.survCore === 'obsidian' ? 1.16 : 1.10));
            }
            BO.ZoneThrill?.refit(w);
            if (w.mag > w.stats.magSize) w.mag = w.stats.magSize;
            if (rebuildVm) P.rebuildViewmodel?.();
            return w;
        }

        open(slotIndex = 0) {
            const P = BO.Player;
            if (!P.weapons.length) {
                this.mode?.toast('You are not carrying a weapon to customize.');
                return;
            }
            const slot = BO.Math.clamp(slotIndex, 0, P.weapons.length - 1);
            this.uiOpen = { slot, tab: 'attachments' };
            if (document.pointerLockElement) document.exitPointerLock();
            this.render();
        }

        close(silent = false) {
            if (!this.uiOpen) return;
            this.uiOpen = null;
            this.el?.remove();
            this.el = null;
            if (!silent && BO.State.screen === 'playing') BO.App?._safePointerLock?.();
        }

        handleKey(e) {
            if (!this.uiOpen) return false;
            if (e.code === 'Escape') { e.preventDefault(); this.close(); }
            return true;
        }

        render() {
            const st = this.uiOpen;
            if (!st || !this.mode) return;
            if (!this.el) {
                this.el = document.createElement('div');
                this.el.className = 'zt-box zt-armory';
                document.body.appendChild(this.el);
                this.el.addEventListener('click', (e) => this.onClick(e));
            }
            const P = BO.Player;
            const m = this.mode;
            const w = P.weapons[st.slot] || P.weapons[0];
            if (!w) return this.close();
            const spec = BO.WeaponsData.get(w.cfg.id);
            const melee = !spec || spec.kind === 'melee' || spec.kind === 'magic';
            const rar = BO.ZoneThrill ? BO.ZoneThrill.describe({ rarity: w.cfg.rarity || 'common', perks: w.cfg.perks || [], title: w.cfg.title }, w.stats.shortName || spec?.name) : null;
            const curRarIdx = Math.max(0, RARITY_LADDER.indexOf(w.cfg.rarity || 'common'));
            const nextRar = RARITY_LADDER[curRarIdx + 1] || null;
            const have = m.points;
            const costStr = (cost) => Object.entries(cost).map(([k, v]) => `${BO.SurvivalItemName(k)} ×${v} (${have[k] || 0})`).join(', ');

            const wTabs = P.weapons.map((wp, idx) => `<button data-arm-slot="${idx}" class="${idx === st.slot ? 'on' : ''}">Slot ${idx + 1}: ${esc(wp.stats.shortName || wp.stats.name)}</button>`).join('');
            const modeTabs = ['attachments', 'anvil', 'camos'].map((t) => `<button data-arm-tab="${t}" class="${st.tab === t ? 'on' : ''}">${t === 'attachments' ? '3D Attachments' : t === 'anvil' ? 'Resonance Anvil' : 'Paint & Camos'}</button>`).join('');

            let content = '';
            if (st.tab === 'attachments') {
                if (melee) {
                    content = `<p class="sv-muted" style="padding:14px">Melee & Wonder weapons do not take rail attachments — switch to <b>Resonance Anvil</b> or <b>Paint & Camos</b> to temper rarity, traits and Elemental Cores!</p>`;
                } else {
                    const slots = ['optic', 'muzzle', 'underbarrel', 'magazine', 'stock'];
                    content = slots.map((sKey) => {
                        const opts = BO.AttachmentsData.ATTACHMENTS[sKey] || [];
                        const cur = w.cfg.attachments?.[sKey] || opts[0]?.id;
                        const kitCost = SLOT_COST[sKey];
                        const afford = m.canAfford(kitCost);
                        return `<div class="zt-arm-group"><h4>${sKey.toUpperCase()} <small>Fitting cost: ${esc(costStr(kitCost))}</small></h4>
                            <div class="zt-box-grid">${opts.map((o, idx) => {
                                const active = cur === o.id;
                                const free = idx === 0;
                                return `<button data-arm-att="${sKey}:${o.id}" class="${active ? 'equipped' : ''}" ${!active && !free && !afford ? 'disabled' : ''}>
                                    <b>${active ? '✓ ' : ''}${esc(o.name)}</b><small>${esc(o.desc)}</small></button>`;
                            }).join('')}</div></div>`;
                    }).join('');
                }
            } else if (st.tab === 'anvil') {
                const tCost = nextRar ? TEMPER_COST[nextRar] : null;
                const canTemper = tCost && m.canAfford(tCost);
                const rerollCost = { quartz: 2, scrap: 3 };
                const canReroll = (w.cfg.perks?.length > 0 || curRarIdx > 0) && m.canAfford(rerollCost);
                content = `<div class="zt-arm-group"><h4>RARITY & TRAIT FORGING</h4>
                    <div class="zt-box-grid">
                        <button data-arm-temper ${canTemper ? '' : 'disabled'}>
                            <b>${nextRar ? 'Temper to ' + nextRar.toUpperCase() : '✓ Maximum Rarity (Legendary)'}</b>
                            <small>${tCost ? 'Cost: ' + esc(costStr(tCost)) + ' · boosts damage & unlocks extra weapon trait!' : 'This weapon has reached peak rarity.'}</small>
                        </button>
                        <button data-arm-reroll ${canReroll ? '' : 'disabled'}>
                            <b>Reroll Weapon Traits</b>
                            <small>Cost: ${esc(costStr(rerollCost))} · Current: ${esc(rar?.traits?.join(', ') || 'None')}</small>
                        </button>
                    </div></div>
                    <div class="zt-arm-group"><h4>ELEMENTAL RESONANCE CORES <small>Socket one active core onto this weapon</small></h4>
                    <div class="zt-box-grid">${Object.values(CORES).map((c) => {
                        const on = w.cfg.survCore === c.id;
                        const ok = m.canAfford(c.cost);
                        return `<button data-arm-core="${c.id}" class="${on ? 'equipped' : ''}" ${!on && !ok ? 'disabled' : ''}>
                            <b style="color:${c.color}">${on ? '✓ ' : ''}${esc(c.name)}</b>
                            <small>${esc(c.desc)}<br>Cost: ${esc(costStr(c.cost))}</small></button>`;
                    }).join('')}</div></div>`;
            } else {
                const camos = BO.AttachmentsData.CAMOS || [];
                content = `<div class="zt-arm-group"><h4>WEAPON FINISHES</h4><div class="zt-box-grid">${camos.map((cm) => {
                    const on = (w.cfg.camo || 'default') === cm.id;
                    const cost = cm.id === 'default' ? {} : cm.id === 'gold' ? { gold: 2 } : cm.id === 'dark_matter' ? { obsidian: 2, aetherShard: 1 } : { resin: 1, herbs: 1 };
                    const ok = Object.keys(cost).length === 0 || m.canAfford(cost);
                    return `<button data-arm-camo="${cm.id}" class="${on ? 'equipped' : ''}" ${!on && !ok ? 'disabled' : ''}>
                        <b>${on ? '✓ ' : ''}${esc(cm.name)}</b>
                        <small>${Object.keys(cost).length ? 'Cost: ' + esc(costStr(cost)) : 'Standard finish'}</small></button>`;
                }).join('')}</div></div>`;
            }

            this.el.innerHTML = `<div class="zt-box-in"><header>
                <b>GUNSMITH & RESONANCE ANVIL</b>
                <span><strong style="color:${rar?.rarity?.color || '#cfe8df'}">${esc(rar ? rar.rarity.name + ' ' + rar.title : w.stats.name)}</strong> · DMG ${Math.round(w.stats.damage)} · MAG ${w.stats.magSize}${w.cfg.survCore ? ' · ' + esc(CORES[w.cfg.survCore].name) : ''}</span>
                <button data-arm-close>Close · Esc</button></header>
                <nav>${wTabs}<span style="flex:1"></span>${modeTabs}</nav>
                <div class="zt-arm-body">${content}</div></div>`;
        }

        onClick(e) {
            const btn = e.target.closest('button');
            if (!btn || !this.uiOpen || !this.mode) return;
            const d = btn.dataset;
            const m = this.mode;
            const P = BO.Player;
            const w = P.weapons[this.uiOpen.slot];
            if (d.armClose !== undefined) return this.close();
            if (d.armSlot !== undefined) { this.uiOpen.slot = +d.armSlot; P.equipSurvivalSlot(this.uiOpen.slot, null, true); this.campaign?.hotbar?.reconcile(); return this.render(); }
            if (d.armTab) { this.uiOpen.tab = d.armTab; return this.render(); }
            if (!w) return;

            if (d.armAtt) {
                const [sKey, attId] = d.armAtt.split(':');
                const opts = BO.AttachmentsData.ATTACHMENTS[sKey] || [];
                const isFactory = opts[0]?.id === attId;
                if (w.cfg.attachments?.[sKey] === attId) return;
                if (!isFactory && !m.spend(SLOT_COST[sKey])) { m.toast('Craft the required kit at a workbench first.'); return; }
                w.cfg.attachments = w.cfg.attachments || {};
                w.cfg.attachments[sKey] = attId;
                P.equipSurvivalSlot(this.uiOpen.slot, null, true);
                this.recomputeWeapon(w, true);
                this.campaign?.mark('gunsmithMods', 1, 35);
                BO.Sound?.playReload?.('bolt');
                m.toast('Fitted ' + (opts.find((o) => o.id === attId)?.name || attId) + '!');
                return this.render();
            }
            if (d.armTemper !== undefined) {
                const idx = Math.max(0, RARITY_LADDER.indexOf(w.cfg.rarity || 'common'));
                const next = RARITY_LADDER[idx + 1];
                if (!next || !m.spend(TEMPER_COST[next])) return;
                const fresh = BO.ZoneThrill?.rollWeapon(w.cfg.id, 4, idx + 1, 2);
                w.cfg.rarity = next;
                if (fresh?.perks) {
                    const keep = new Set([...(w.cfg.perks || []), ...fresh.perks]);
                    w.cfg.perks = [...keep].slice(0, idx + 1);
                }
                if (next === 'legendary' && !w.cfg.title && fresh?.title) w.cfg.title = fresh.title;
                this.recomputeWeapon(w, true);
                this.campaign?.mark('gunsmithMods', 1, 65);
                BO.Sound?.playPaP?.();
                m.toast('Tempered weapon to ' + next.toUpperCase() + '!');
                return this.render();
            }
            if (d.armReroll !== undefined) {
                const idx = Math.max(1, RARITY_LADDER.indexOf(w.cfg.rarity || 'common'));
                if (!m.spend({ quartz: 2, scrap: 3 })) return;
                const fresh = BO.ZoneThrill?.rollWeapon(w.cfg.id, 4, idx, 2);
                if (fresh?.perks) w.cfg.perks = fresh.perks.slice(0, idx);
                this.recomputeWeapon(w, true);
                BO.Sound?.playPerkBuy?.();
                m.toast('Weapon traits reforged!');
                return this.render();
            }
            if (d.armCore) {
                const core = CORES[d.armCore];
                if (!core || w.cfg.survCore === core.id) return;
                if (!m.spend(core.cost)) return;
                w.cfg.survCore = core.id;
                this.recomputeWeapon(w, true);
                this.campaign?.mark('gunsmithMods', 1, 50);
                BO.Sound?.playPaP?.();
                m.toast('Socketed ' + core.name + '!');
                return this.render();
            }
            if (d.armCamo) {
                const cm = d.armCamo;
                if ((w.cfg.camo || 'default') === cm) return;
                const cost = cm === 'default' ? {} : cm === 'gold' ? { gold: 2 } : cm === 'dark_matter' ? { obsidian: 2, aetherShard: 1 } : { resin: 1, herbs: 1 };
                if (Object.keys(cost).length && !m.spend(cost)) return;
                w.cfg.camo = cm;
                P.equipSurvivalSlot(this.uiOpen.slot, null, true);
                this.recomputeWeapon(w, true);
                BO.Sound?.playUIClick?.();
                m.toast('Applied finish!');
                return this.render();
            }
        }
    }

    BO.ZoneArmory = new ZoneArmory();
    BO.ZoneArmory.CORES = CORES;
})(window.BO);
;

/* --- src/systems/ZoneDungeons.js --- */
/* ============================================================================
   BLACKOUT OPS — Dungeons and the boss arena
   Nine hand-designed dungeons, each entered from a doorway in the world and
   built as its own sealed space beyond the map edge when you step inside:
   small cellars to seven-room bunkers; rooms full of enemies, puzzles
   (levers, braziers, valves, fuses, keypad codes, a timed vault, a dark
   maze), fire hazards, end chests and bosses. Doors ahead stay locked until
   the room is cleared or its puzzle solved.
   The arena is a separate space the Pit Masters send you to for a boss duel;
   a portal home opens when the boss falls, with time to loot.
============================================================================ */
(function (BO) {
    'use strict';

    const SYMBOLS = [['▲', 0xff5a4a, 'red triangle'], ['●', 0x4aa8ff, 'blue circle'], ['■', 0x5fd17a, 'green square'], ['◆', 0xffd27a, 'gold diamond'], ['✚', 0xb26bff, 'violet cross']];

    /* Room: w,d (m), kind tags. enemies: count, champ: champion count, boss: boss spec id,
       puzzle: {type,...}, chest: tier, hazard: 'fire', dark: true, ore: n deposits, note: text. */
    const DUNGEONS = [
        { id: 'cellar', name: 'Kessler Root Cellar', size: 'Small', near: 'farmhouse', theme: 0x6a5a48, tier: 1,
            blurb: 'A farm cellar the family barricaded from the inside. Something is still down there.',
            rooms: [{ w: 8, d: 8, enemies: 3, note: 'Scratched into the shelf: "Ma says don\'t open the back room."' }, { w: 7, d: 7, enemies: 2, champ: 1, chest: 1 }] },
        { id: 'crypt', name: 'Saint Ansel Crypt', size: 'Small', near: 'church', theme: 0x5a5866, tier: 1,
            blurb: 'Beneath the church: an ossuary and four cold braziers.',
            rooms: [{ w: 9, d: 9, enemies: 3 }, { w: 12, d: 12, puzzle: { type: 'braziers', count: 4, time: 25 }, note: 'Carved over the gate: "Kindle all four before the first goes cold." (25 seconds once you light the first.)' }, { w: 6, d: 6, chest: 2 }] },
        { id: 'mine', name: 'Pinebreak Mine Shaft', size: 'Medium', near: 'mill', theme: 0x5a4a3a, tier: 2,
            blurb: 'An abandoned seam with live ore, three missing fuses and a dead lift.',
            rooms: [{ w: 10, d: 12, enemies: 3, ore: 4 }, { w: 12, d: 10, enemies: 4, puzzle: { type: 'fuses', count: 3 }, ore: 3, note: 'Foreman\'s board: "LIFT FUSES REMOVED — find all 3 and refit the panel."' }, { w: 10, d: 10, enemies: 5, champ: 1, ore: 5 }, { w: 7, d: 7, chest: 2 }] },
        { id: 'pumps', name: 'Spillway Pump Station', size: 'Medium', near: 'pumphouse', theme: 0x3f5a64, tier: 2,
            blurb: 'A flooded control level. Set the valves to drain it.',
            rooms: [{ w: 10, d: 10, enemies: 4 }, { w: 12, d: 12, puzzle: { type: 'valves', count: 3 }, note: 'Pressure chart on the wall: the gauge panel shows the setting each valve needs.' }, { w: 14, d: 10, enemies: 6, champ: 1 }, { w: 7, d: 7, chest: 3 }] },
        { id: 'bunker', name: 'Sable Bunker K-7', size: 'Large', near: 'office', theme: 0x46503f, tier: 3,
            blurb: 'A Sable Company command bunker: barracks, an armoury behind a code lock, and whatever they were keeping in the cells.',
            rooms: [{ w: 12, d: 10, enemies: 5 }, { w: 10, d: 12, enemies: 4, note: 'CODE' }, { w: 12, d: 10, puzzle: { type: 'keypad', digits: 3 }, enemies: 3 }, { w: 14, d: 12, enemies: 7, champ: 2 }, { w: 16, d: 16, boss: 'boss_colossus', bossName: 'K-7 Containment Breaker' }, { w: 8, d: 8, chest: 4 }] },
        { id: 'hive', name: 'The Hive Tunnels', size: 'Large', near: 'cabin', region: 'pine', theme: 0x4a3a2a, tier: 3,
            blurb: 'Under the forest the nests connect. Room after room of infected, and the matron at the heart.',
            rooms: [{ w: 12, d: 12, enemies: 7 }, { w: 14, d: 12, enemies: 9, champ: 1 }, { w: 12, d: 14, enemies: 10, champ: 1, dark: true }, { w: 14, d: 14, enemies: 12, champ: 2 }, { w: 18, d: 18, boss: 'boss_hydra_matron', bossName: 'Hive Matron' }, { w: 8, d: 8, chest: 4 }] },
        { id: 'vault', name: 'Frostline Cold-Storage Vault', size: 'Medium', near: 'lodge', theme: 0x6a7a88, tier: 3,
            blurb: 'An alarm trips the moment you enter. Reach the vault before lockdown.',
            rooms: [{ w: 10, d: 10, puzzle: { type: 'timed', time: 75 }, note: 'ALARM: 75 s to vault lockdown. Run.' }, { w: 12, d: 10, enemies: 5 }, { w: 10, d: 14, enemies: 4, hazard: 'fire' }, { w: 8, d: 8, chest: 3 }] },
        { id: 'furnace', name: 'Cinder Furnace Halls', size: 'Medium', near: 'control', theme: 0x6a3a2a, tier: 3,
            blurb: 'Gas jets still fire on a cycle. Something three-headed sleeps by the furnace.',
            rooms: [{ w: 12, d: 10, enemies: 5, hazard: 'fire' }, { w: 12, d: 14, enemies: 6, hazard: 'fire', champ: 1 }, { w: 16, d: 16, boss: 'boss_cerberus', bossName: 'Furnace Hound' }, { w: 8, d: 8, chest: 3 }] },
        { id: 'sublevel', name: 'Black Pine Sublevel B3', size: 'Large', near: 'lab', theme: 0x9aa8b0, tier: 4,
            blurb: 'The research floor nobody was cleared for: a lever-locked containment wing, a lightless maze and Subject Zero.',
            rooms: [{ w: 12, d: 12, enemies: 6, note: 'LEVERS' }, { w: 14, d: 12, puzzle: { type: 'levers', count: 4 }, enemies: 3 }, { w: 12, d: 18, enemies: 8, dark: true, champ: 1 }, { w: 14, d: 14, enemies: 9, champ: 2 }, { w: 12, d: 12, puzzle: { type: 'valves', count: 3 } }, { w: 18, d: 18, boss: 'boss_nyx', bossName: 'Subject Zero' }, { w: 8, d: 8, chest: 5 }] }
    ];

    const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

    /* ================================================================ space builder */
    class Space {
        constructor(mode, ox, oz, color) {
            this.mode = mode; this.ox = ox; this.oz = oz; this.color = color;
            this.meshes = []; this.worldRegistered = []; this.cols = []; this.markers = []; this.doors = []; this.portals = [];
        }
        mat(c, opts = {}) { return new THREE.MeshStandardMaterial({ color: new THREE.Color(c).convertSRGBToLinear(), roughness: 0.9, ...opts }); }
        box(x, y, z, w, h, d, c, collide = true, opts) {
            const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), this.mat(c, opts));
            mesh.position.set(x, y, z);
            mesh.receiveShadow = true;
            this.mode.scene.add(mesh);
            this.meshes.push(mesh);
            if (collide) {
                const col = { minX: x - w / 2, maxX: x + w / 2, minY: y - h / 2, maxY: y + h / 2, minZ: z - d / 2, maxZ: z + d / 2, active: true, navIgnore: true };
                BO.World.colliders.push(col);
                BO.World.worldMeshes.push(mesh);
                mesh.updateMatrixWorld();
                this.cols.push(col);
                this.worldRegistered.push(mesh);
                mesh.userData.col = col;
            }
            return mesh;
        }
        /** Room centred at (cx, cz) with door gaps on north (+z) / south (-z). */
        room(cx, cz, w, d, h, doors) {
            const c = this.color, t = 0.4, gap = 2.6;
            this.box(cx, -0.25, cz, w + t * 2, 0.5, d + t * 2, new THREE.Color(c).multiplyScalar(0.7).getHex());
            this.box(cx, h + 0.2, cz, w + t * 2, 0.4, d + t * 2, new THREE.Color(c).multiplyScalar(0.5).getHex(), false);
            for (const side of [-1, 1]) this.box(cx + side * (w / 2 + t / 2), h / 2, cz, t, h, d + t * 2, c);
            for (const [side, open] of [[-1, doors.s], [1, doors.n]]) {
                const z = cz + side * (d / 2 + t / 2);
                if (!open) { this.box(cx, h / 2, z, w, h, t, c); continue; }
                const seg = (w - gap) / 2;
                this.box(cx - gap / 2 - seg / 2, h / 2, z, seg, h, t, c);
                this.box(cx + gap / 2 + seg / 2, h / 2, z, seg, h, t, c);
                this.box(cx, h - 0.4, z, gap, 0.8, t, c);
            }
            // Corner stone pillars for architectural depth & cover.
            for (const sx of [-1, 1]) for (const sz of [-1, 1]) {
                this.box(cx + sx * (w / 2 - 0.22), h / 2, cz + sz * (d / 2 - 0.22), 0.44, h, 0.44, new THREE.Color(c).multiplyScalar(0.82).getHex());
            }
            // Wall lamps.
            return [-1, 1].map((side) => this.box(cx + side * (w / 2 - 0.05), h * 0.7, cz, 0.08, 0.3, 0.6, 0xffe2a8, false, { emissive: new THREE.Color(0xffc870), emissiveIntensity: 1.4 }));
        }
        door(x, z, w, h) {
            const mesh = this.box(x, h / 2, z, w, h, 0.3, 0x3a3a3a, true, { metalness: 0.6 });
            const dObj = {
                mesh, h, opening: false,
                open: () => {
                    if (dObj.opening) return;
                    dObj.opening = true;
                    mesh.userData.col.active = false;
                    const idx = BO.World.worldMeshes.indexOf(mesh);
                    if (idx >= 0) BO.World.worldMeshes.splice(idx, 1);
                    BO.Sound?.playWallBreak?.();
                }
            };
            this.doors.push(dObj);
            return dObj;
        }
        tick(dt, clock) {
            for (const d of this.doors) {
                if (d.opening && d.mesh.visible) {
                    d.mesh.position.y += dt * 4.5;
                    if (d.mesh.position.y > d.h * 1.45) d.mesh.visible = false;
                }
            }
            for (const p of this.portals) {
                p.ring.rotation.z = clock * 1.4;
                p.disc.material.opacity = 0.45 + Math.sin(clock * 3.2) * 0.16;
            }
        }
        marker(mk) { mk.alive = true; this.mode.markers.push(mk); this.markers.push(mk); return mk; }
        dispose() {
            for (const wm of this.worldRegistered) {
                const idx = BO.World.worldMeshes.indexOf(wm);
                if (idx >= 0) BO.World.worldMeshes.splice(idx, 1);
            }
            for (const m of this.meshes) { m.removeFromParent(); m.geometry?.dispose?.(); m.material?.dispose?.(); }
            for (const c of this.cols) {
                c.active = false;
                const idx = BO.World.colliders.indexOf(c);
                if (idx >= 0) BO.World.colliders.splice(idx, 1);
            }
            for (const mk of this.markers) {
                mk.alive = false;
                const idx = this.mode.markers.indexOf(mk);
                if (idx >= 0) this.mode.markers.splice(idx, 1);
            }
            this.meshes = []; this.worldRegistered = []; this.cols = []; this.markers = []; this.doors = []; this.portals = [];
        }
    }

    class ZoneDungeons {
        constructor() { this.state = {}; this.inside = null; }
        get campaign() { return this.mode?.campaign; }

        start(mode, saved) {
            this.stop();
            this.mode = mode;
            this.state = JSON.parse(JSON.stringify(saved?.state || {}));
            this.inside = null;
            this.entrances = [];
            this.objects = [];
            for (const d of DUNGEONS) this.placeEntrance(d);
        }

        stop() {
            if (this.inside) this.leave(true);
            for (const o of this.objects || []) o.removeFromParent?.();
            this.objects = [];
            this.mode = null;
        }

        snapshot() { return { state: this.state }; }
        st(id) { return this.state[id] || (this.state[id] = { cleared: false, chest: false, boss: false, visits: 0 }); }

        placeEntrance(d) {
            const m = this.mode;
            const poi = BO.Zone.pois.find((p) => p.type === d.near && (!d.region || p.region === d.region)) || BO.Zone.pois.find((p) => p.type === d.near);
            if (!poi) return;
            const x = poi.x - poi.w / 2 - 4, z = poi.z - poi.d / 2 - 3;
            const y = BO.World.getGroundHeight(x, z, (poi.y || 0) + 2);
            const g = new THREE.Group();
            const stone = new THREE.MeshStandardMaterial({ color: 0x5a5650, roughness: 0.95 });
            const add = (w, h, dd, px, py, pz, mat = stone) => { const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, dd), mat); mesh.position.set(px, py, pz); mesh.castShadow = true; g.add(mesh); };
            add(0.5, 2.6, 0.5, -1.1, 1.3, 0); add(0.5, 2.6, 0.5, 1.1, 1.3, 0); add(2.8, 0.5, 0.6, 0, 2.75, 0);
            add(1.8, 2.2, 0.1, 0, 1.1, 0.05, new THREE.MeshBasicMaterial({ color: 0x050607 }));
            const glow = new THREE.MeshStandardMaterial({ color: 0xffd27a, emissive: new THREE.Color(0xffa030), emissiveIntensity: 1.2 });
            add(0.15, 0.15, 0.15, -1.1, 2.75, 0.32, glow); add(0.15, 0.15, 0.15, 1.1, 2.75, 0.32, glow);
            g.position.set(x, y, z);
            m.scene.add(g);
            this.objects.push(g);
            const tags = [...new Set(d.rooms.flatMap((r) => [r.puzzle ? 'puzzle' : '', r.boss ? 'boss' : '', r.chest ? 'chest' : '', r.enemies >= 7 ? 'swarming' : '']).filter(Boolean))];
            const mk = { id: 'dgn:' + d.id, x, y, z: z + 1, name: d.name, label: 'Enter ' + d.name + ' (' + d.size.toLowerCase() + (tags.length ? ' · ' + tags.join(', ') : '') + ')', alive: true, dungeon: d.id, reach: 3 };
            m.markers.push(mk);
            this.entrances.push({ d, x, y, z, mk });
        }

        /* ------------------------------------------------------------ entering */
        enter(id) {
            const m = this.mode;
            const d = typeof id === 'object' && id ? id : DUNGEONS.find((x) => x.id === id);
            if (!d || this.inside) return;
            const ent = this.entrances.find((e) => e.d.id === d.id) || { x: BO.Player.pos.x, y: BO.Player.pos.y, z: BO.Player.pos.z };
            const idx = DUNGEONS.indexOf(d);
            const ox = 2200 + idx * 500, oz = 0;
            const sp = new Space(m, ox, oz, d.theme);
            const s = this.st(d.id);
            s.visits++;
            const run = { d, sp, rooms: [], ret: { x: ent.x, y: ent.y, z: ent.z + 2.5 }, timer: null, done: s.cleared };
            const H = 4.2;
            let z = oz;
            d.rooms.forEach((r, i) => {
                const cz = z + r.d / 2;
                const lamps = sp.room(ox, cz, r.w, r.d, H, { s: true, n: i < d.rooms.length - 1 });
                if (r.dark) for (const l of lamps) l.visible = false;
                const room = { r, i, cx: ox, cz, x0: ox - r.w / 2, x1: ox + r.w / 2, z0: z, z1: z + r.d, entered: false, cleared: false, enemies: [], solved: !r.puzzle };
                if (i < d.rooms.length - 1) {
                    // Corridor to the next room.
                    const cz2 = z + r.d + 2;
                    sp.box(ox, -0.25, cz2, 3.4, 0.5, 4, new THREE.Color(d.theme).multiplyScalar(0.6).getHex());
                    sp.box(ox - 1.5, H / 2, cz2, 0.4, H, 4, d.theme); sp.box(ox + 1.5, H / 2, cz2, 0.4, H, 4, d.theme);
                    sp.box(ox, H + 0.2, cz2, 3.4, 0.4, 4, 0x2a2a2a, false);
                    room.door = s.cleared ? null : sp.door(ox, z + r.d + 0.6, 2.6, H - 0.6);
                }
                if (i === 0) sp.box(ox, H / 2, z - 0.6, 3, H, 0.4, d.theme); // sealed entry behind you
                run.rooms.push(room);
                this.dress(run, room);
                z += r.d + 4;
            });
            // Portal home at the start and (after the chest) at the end.
            const startZ = oz + 1.2;
            this.portal(run, ox - (d.rooms[0].w / 2 - 1.2), startZ, 'Leave the dungeon');
            run.spawn = { x: ox, z: oz + 2 };
            this.inside = run;
            this.light = this.light || new THREE.PointLight(0xffd8a0, 1.1, 22, 1.6);
            m.scene.add(this.light);
            const p = BO.Player;
            p.pos.set(ox, 0.1, oz + 2.2);
            p.vel.set(0, 0, 0);
            p.yaw = Math.PI;
            BO.Events.emit('hud:banner', { title: d.name.toUpperCase(), sub: d.size.toUpperCase() + ' DUNGEON · ' + d.rooms.length + ' ROOMS' + (s.cleared ? ' · CLEARED' : ''), color: '#ffd27a' });
            m.toast(d.blurb);
            this.campaign.mark('dungeonVisits', 1, 0);
            this.campaign.mark('dgn_enter_' + id, 1, 0);
        }

        portal(run, x, z, label) {
            const sp = run.sp;
            const ring = new THREE.Mesh(new THREE.TorusGeometry(1.0, 0.12, 8, 24), new THREE.MeshBasicMaterial({ color: new THREE.Color(0x8fe3c8).convertSRGBToLinear() }));
            ring.position.set(x, 1.3, z);
            const disc = new THREE.Mesh(new THREE.CircleGeometry(0.95, 24), new THREE.MeshBasicMaterial({ color: new THREE.Color(0x3fcfaa).convertSRGBToLinear(), transparent: true, opacity: 0.55, side: THREE.DoubleSide }));
            disc.position.set(x, 1.3, z);
            this.mode.scene.add(ring, disc);
            sp.meshes.push(ring, disc);
            sp.portals.push({ ring, disc });
            sp.marker({ id: 'dgnexit:' + x.toFixed(1) + ':' + z.toFixed(1), x, y: 0, z, name: 'Portal', label, dgnExit: true, reach: 2.2 });
        }

        /** Notes, puzzles, ore, fire grates and the chest for a room (enemies spawn on entry). */
        dress(run, room) {
            const sp = run.sp, r = room.r, d = run.d, s = this.st(d.id);
            const x0 = room.x0, z0 = room.z0;
            if (r.hazard === 'fire') {
                room.fireGrates = [];
                room.fireCones = [];
                for (let gz = z0 + 1; gz < room.z1 - 0.8; gz += 4) {
                    const grate = sp.box(room.cx, 0.03, gz, r.w - 1.6, 0.06, 1.7, 0x3a261e, false, { metalness: 0.75, emissive: new THREE.Color(0xff4a00), emissiveIntensity: 0.12 });
                    room.fireGrates.push(grate);
                    for (const ox of [-r.w * 0.28, 0, r.w * 0.28]) {
                        const cone = new THREE.Mesh(new THREE.ConeGeometry(0.55, 2.5, 7), new THREE.MeshBasicMaterial({ color: new THREE.Color(0xff6a1a).convertSRGBToLinear(), transparent: true, opacity: 0.78 }));
                        cone.position.set(room.cx + ox, 1.25, gz);
                        cone.visible = false;
                        this.mode.scene.add(cone);
                        sp.meshes.push(cone);
                        room.fireCones.push(cone);
                    }
                }
            }
            if (r.note) {
                let text = r.note;
                if (text === 'CODE') { run.code = run.code || [1 + Math.floor(Math.random() * 9), Math.floor(Math.random() * 10), Math.floor(Math.random() * 10)]; text = 'A torn duty roster. Scrawled on the back: "Armoury code ' + run.code.join('-') + '. Burn this."'; }
                if (text === 'LEVERS') { run.order = run.order || this.shuffle([0, 1, 2, 3]); text = 'Containment protocol, page 4: "Release order — ' + run.order.map((k) => SYMBOLS[k][2]).join(', then ') + '."'; }
                sp.box(x0 + 1, 1.0, z0 + 1.5, 0.6, 0.05, 0.4, 0xe8e0c8, false);
                sp.marker({ id: 'dgnnote:' + d.id + room.i, x: x0 + 1, y: 0, z: z0 + 1.5, name: 'Note', label: 'Read the note', dgnNote: text, reach: 2 });
            }
            if (r.ore) {
                const kinds = ['iron', 'coal', 'copper', 'gold', 'quartz', 'sulfur'];
                run.deposits = run.deposits || [];
                for (let k = 0; k < r.ore; k++) {
                    const ox = x0 + 1.2 + Math.random() * (r.w - 2.4), oz = z0 + 1.5 + Math.random() * (r.d - 3);
                    const depId = 'dnode:' + d.id + ':' + room.i + ':' + k + ':' + s.visits;
                    this.campaign.pack.createDeposit?.(depId, { kind: kinds[(k + room.i) % kinds.length], x: ox, y: 0, z: oz });
                    run.deposits.push(depId);
                }
            }
            if (r.puzzle && !s.cleared) this.buildPuzzle(run, room);
            if (r.chest) {
                const cx = room.cx, cz = room.z1 - 2;
                sp.box(cx, 0.4, cz, 1.4, 0.8, 0.9, s.chest ? 0x2a2a2a : 0x8a6a2a, true, s.chest ? {} : { emissive: new THREE.Color(0xffb43a), emissiveIntensity: 0.35, metalness: 0.4 });
                if (!s.chest) sp.marker({ id: 'dgnchest:' + d.id, x: cx, y: 0, z: cz - 0.8, name: d.name + ' chest', label: 'Open the ' + d.name + ' chest', dgnChest: r.chest, reach: 2.4 });
                this.portal(run, cx + r.w / 2 - 1.5, cz, 'Portal home');
            }
        }

        shuffle(a) { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

        /* ------------------------------------------------------------ puzzles */
        buildPuzzle(run, room) {
            const sp = run.sp, pz = room.r.puzzle, d = run.d;
            const P = room.pz = { type: pz.type, state: [], need: [] };
            const along = (k, n) => room.x0 + (k + 1) * room.r.w / (n + 1);
            const wallZ = room.z1 - 0.8;
            if (pz.type === 'levers') {
                run.order = run.order || this.shuffle([0, 1, 2, 3]);
                P.need = run.order; P.state = [];
                for (let k = 0; k < pz.count; k++) {
                    const x = along(k, pz.count);
                    sp.box(x, 1.6, wallZ + 0.3, 0.5, 0.5, 0.1, SYMBOLS[k][1], false, { emissive: new THREE.Color(SYMBOLS[k][1]), emissiveIntensity: 0.6 });
                    P['lever' + k] = sp.box(x, 1.0, wallZ, 0.12, 0.6, 0.12, 0x888888, false);
                    sp.marker({ id: 'pzl:' + k, x, y: 0, z: wallZ - 0.6, name: 'Lever (' + SYMBOLS[k][2] + ')', label: 'Pull the ' + SYMBOLS[k][2] + ' lever', puzzle: { room, k }, reach: 1.8 });
                }
            } else if (pz.type === 'braziers') {
                P.lit = new Array(pz.count).fill(false);
                for (let k = 0; k < pz.count; k++) {
                    const a = k / pz.count * Math.PI * 2;
                    const x = room.cx + Math.cos(a) * room.r.w * 0.32, z = (room.z0 + room.z1) / 2 + Math.sin(a) * room.r.d * 0.32;
                    sp.box(x, 0.5, z, 0.6, 1.0, 0.6, 0x4a4440);
                    P['fire' + k] = sp.box(x, 1.25, z, 0.4, 0.5, 0.4, 0xff7a1a, false, { emissive: new THREE.Color(0xff6a00), emissiveIntensity: 1.5 });
                    P['fire' + k].visible = false;
                    sp.marker({ id: 'pzl:' + k, x, y: 0, z: z - 0.7, name: 'Brazier', label: 'Light the brazier', puzzle: { room, k }, reach: 1.8 });
                }
            } else if (pz.type === 'valves') {
                P.need = Array.from({ length: pz.count }, () => Math.floor(Math.random() * 4));
                P.state = Array.from({ length: pz.count }, () => 0);
                sp.box(room.cx, 2.2, wallZ + 0.3, 2.4, 0.9, 0.1, 0x22303a, false);
                P.gauge = sp.marker({ id: 'pzlg', x: room.cx, y: 0, z: wallZ - 0.8, name: 'Gauge panel', label: 'Read the gauge panel', dgnNote: 'Required valve settings (left to right): ' + P.need.map((n) => n + 1).join(' · ') + '. Each turn moves a valve one step (1→2→3→4→1).', reach: 2 });
                for (let k = 0; k < pz.count; k++) {
                    const x = room.x0 + 1.4 + k * 2.2, z = room.z0 + 2.2;
                    P['valve' + k] = sp.box(x, 1.0, z, 0.7, 0.7, 0.12, 0xb03a2a, false, { metalness: 0.6 });
                    sp.marker({ id: 'pzl:' + k, x, y: 0, z: z + 0.6, name: 'Valve ' + (k + 1), label: 'Turn valve ' + (k + 1) + ' (now 1)', puzzle: { room, k }, reach: 1.7 });
                }
            } else if (pz.type === 'fuses') {
                P.found = 0; P.inserted = false;
                const spots = this.shuffle(run.rooms.slice(0, room.i + 1).flatMap((rm) => [[rm.x0 + 0.9, rm.z0 + rm.r.d * 0.7], [rm.x1 - 0.9, rm.z0 + rm.r.d * 0.35]])).slice(0, pz.count);
                while (spots.length < pz.count) spots.push([room.x0 + 1 + spots.length, room.z0 + 1.5]);
                spots.forEach(([x, z], k) => {
                    const mesh = sp.box(x, 0.3, z, 0.25, 0.25, 0.25, 0xffd27a, false, { emissive: new THREE.Color(0xffd27a), emissiveIntensity: 0.9 });
                    sp.marker({ id: 'pzlf:' + k, x, y: 0, z, name: 'Fuse', label: 'Take the fuse', puzzle: { room, fuse: k, mesh }, reach: 1.6 });
                });
                sp.box(room.cx + 2, 1.4, wallZ + 0.3, 0.9, 1.2, 0.15, 0x3a3a3a, false);
                sp.marker({ id: 'pzlp', x: room.cx + 2, y: 0, z: wallZ - 0.6, name: 'Lift panel', label: 'Refit the fuses', puzzle: { room, panel: true }, reach: 1.8 });
            } else if (pz.type === 'keypad') {
                run.code = run.code || [1 + Math.floor(Math.random() * 9), Math.floor(Math.random() * 10), Math.floor(Math.random() * 10)];
                P.state = [0, 0, 0];
                for (let k = 0; k < 3; k++) {
                    const x = room.cx - 1.2 + k * 1.2;
                    sp.box(x, 1.3, wallZ + 0.25, 0.8, 0.8, 0.1, 0x2a3a2a, false, { emissive: new THREE.Color(0x3fcf7a), emissiveIntensity: 0.3 });
                    sp.marker({ id: 'pzl:' + k, x, y: 0, z: wallZ - 0.5, name: 'Dial ' + (k + 1), label: 'Turn dial ' + (k + 1) + ' (shows 0)', puzzle: { room, k }, reach: 1.1 });
                }
                sp.marker({ id: 'pzlok', x: room.cx + 2.4, y: 0, z: wallZ - 0.5, name: 'Keypad', label: 'Press ENTER on the keypad', puzzle: { room, enter: true }, reach: 1.3 });
            } else if (pz.type === 'timed') {
                room.solved = true; // the doors are open; the clock is the puzzle
                run.timed = { until: null, time: pz.time, room };
            }
        }

        puzzleAct(mk) {
            const { room } = mk.puzzle;
            const P = room.pz;
            const m = this.mode;
            const run = this.inside;
            if (!P || room.solved) return;
            if (P.type === 'levers') {
                const k = mk.puzzle.k;
                P['lever' + k].rotation.x = 0.8;
                P.state.push(k);
                const okSoFar = P.state.every((v, i) => v === P.need[i]);
                BO.Sound?.playWallHit?.();
                if (!okSoFar) {
                    m.toast('Wrong order. The levers snap back — and something wakes up.');
                    P.state = [];
                    for (let i = 0; i < 4; i++) if (P['lever' + i]) P['lever' + i].rotation.x = 0;
                    this.spawnIn(run, room, 2, 0);
                } else if (P.state.length === P.need.length) this.solve(run, room, 'The containment locks release.');
                else m.toast('Click. (' + P.state.length + '/' + P.need.length + ')');
            } else if (P.type === 'braziers') {
                const k = mk.puzzle.k;
                if (P.lit[k]) return;
                if (!P.lit.some(Boolean)) P.until = m.clock + room.r.puzzle.time;
                P.lit[k] = true;
                P['fire' + k].visible = true;
                BO.Sound?.playTone?.(300, 600, 0.3, 'triangle', 0.2);
                if (P.lit.every(Boolean)) this.solve(run, room, 'All four braziers burn. The gate grinds open.');
                else m.toast(P.lit.filter(Boolean).length + '/' + P.lit.length + ' lit — ' + Math.max(0, Math.ceil(P.until - m.clock)) + ' s left.');
            } else if (P.type === 'valves') {
                const k = mk.puzzle.k;
                P.state[k] = (P.state[k] + 1) % 4;
                P['valve' + k].rotation.z = P.state[k] * Math.PI / 2;
                mk.label = 'Turn valve ' + (k + 1) + ' (now ' + (P.state[k] + 1) + ')';
                BO.Sound?.playReload?.('in');
                if (P.state.every((v, i) => v === P.need[i])) this.solve(run, room, 'Pressure equalises. The water drains and the hatch unlocks.');
            } else if (P.type === 'fuses') {
                if (mk.puzzle.fuse !== undefined) {
                    mk.alive = false; mk.puzzle.mesh.visible = false; P.found++;
                    m.toast('Fuse ' + P.found + '/' + room.r.puzzle.count + '.');
                } else if (mk.puzzle.panel) {
                    if (P.found < room.r.puzzle.count) m.toast('The panel needs ' + room.r.puzzle.count + ' fuses. You have ' + P.found + '.');
                    else this.solve(run, room, 'Fuses refitted. The lift hums back to life.');
                }
            } else if (P.type === 'keypad') {
                if (mk.puzzle.enter) {
                    if (P.state.every((v, i) => v === run.code[i])) this.solve(run, room, 'ACCESS GRANTED. The armoury door slides open.');
                    else { m.toast('ACCESS DENIED. An alarm wails.'); this.spawnIn(run, room, 3, 0); }
                } else {
                    const k = mk.puzzle.k;
                    P.state[k] = (P.state[k] + 1) % 10;
                    mk.label = 'Turn dial ' + (k + 1) + ' (shows ' + P.state[k] + ')';
                    BO.Sound?.playUIClick?.();
                }
            }
        }

        solve(run, room, msg) {
            room.solved = true;
            this.campaign.mark('puzzles', 1, 40);
            BO.ZoneThrill?.xp(40, 'Puzzle');
            BO.Events.emit('hud:banner', { title: 'PUZZLE SOLVED', sub: msg.toUpperCase(), color: '#8fe3c8' });
            this.tryOpen(run, room);
        }

        tryOpen(run, room) {
            if (!room.solved) return;
            if (room.enemies.some((z) => z.alive && !z.despawned)) return;
            room.cleared = true;
            if (room.door) { room.door.open(); room.door = null; this.mode.toast('The way ahead is open.'); }
        }

        /* ------------------------------------------------------------ enemies */
        spawnIn(run, room, n, champs, bossSpec, bossName) {
            const m = this.mode, c = m.campaign;
            const region = BO.Zone.regionAt(run.ret.x, run.ret.z).id;
            c.selectedEnemies = c.getPool(region);
            for (let i = 0; i < n; i++) {
                const x = room.x0 + 1 + Math.random() * (room.r.w - 2), z = room.z0 + room.r.d * 0.45 + Math.random() * room.r.d * 0.5;
                const zb = m.spawnInfected(x, 0.05, z, 'normal', null, true);
                if (!zb) continue;
                zb.dungeon = run.d.id;
                zb.zs = { state: 'hunt', home: { x, z }, x, z, until: 0, seen: m.clock, wander: 0 };
                if (i < champs) BO.ZoneThrill?.makeChampion(zb, run.d.tier >= 3 ? 2 : 1);
                room.enemies.push(zb);
            }
            if (bossSpec) {
                const zb = m.spawnInfected(room.cx, 0.05, room.z0 + room.r.d * 0.7, 'normal', bossSpec, true);
                if (zb) {
                    zb.dungeon = run.d.id;
                    zb.bossLabel = bossName;
                    zb.maxHp = zb.hp = Math.round((900 + run.d.tier * 450) * (m.tierSpec?.hp || 1) * (m.difficultyRules?.hp || 1));
                    zb.damage = Math.round(26 + run.d.tier * 6);
                    zb.speed = 2.8;
                    zb.zs = { state: 'hunt', home: { x: room.cx, z: room.cz }, x: room.cx, z: room.cz, until: 0, seen: m.clock, wander: 0 };
                    room.enemies.push(zb);
                    room.boss = zb;
                    BO.Sound?.playBossIntro?.();
                    BO.Events.emit('hud:banner', { title: bossName.toUpperCase(), sub: 'DUNGEON BOSS', color: '#ff6b5b' });
                }
            }
            m.refreshTargets();
        }

        /* ------------------------------------------------------------ frame */
        update(dt) {
            const m = this.mode;
            const run = this.inside;
            if (!m || !run) return;
            const p = BO.Player;
            // Death or travel took you out: tidy up.
            if (!p.alive) return;
            if (Math.abs(p.pos.x - run.sp.ox) > 120 || p.pos.y < -30) { if (p.pos.y < -30) { p.pos.set(run.spawn.x, 0.2, run.spawn.z); p.vel.set(0, 0, 0); } else { this.leave(true); return; } }
            this.light.position.set(p.pos.x, p.pos.y + 2.2, p.pos.z);
            run.sp.tick(dt, m.clock);
            m.localWeather = 'Clear'; // underground: no rain, snow or ash
            const s = this.st(run.d.id);
            for (const room of run.rooms) {
                const inRoom = p.pos.x > room.x0 && p.pos.x < room.x1 && p.pos.z > room.z0 + 0.5 && p.pos.z < room.z1;
                if (inRoom && !room.entered) {
                    room.entered = true;
                    if (!s.cleared) {
                        if (room.r.enemies) this.spawnIn(run, room, room.r.enemies + Math.floor((this.campaign.day - 1) / 3), room.r.champ || 0);
                        if (room.r.boss && !s.boss) this.spawnIn(run, room, 0, 0, room.r.boss, room.r.bossName);
                        if (room.r.hazard === 'fire') m.toast('Gas jets fire on a cycle — watch the floor glow and move.');
                    }
                    if (run.timed && room === run.timed.room && !run.timed.until && !s.cleared) { run.timed.until = m.clock + run.timed.time; BO.Sound?.playAirRaidSiren?.(); }
                }
                if (room.entered && !room.cleared) this.tryOpen(run, room);
                if (room.pz?.type === 'braziers' && room.pz.until && !room.solved && m.clock > room.pz.until) {
                    room.pz.until = null; room.pz.lit.fill(false);
                    for (let k = 0; k < room.pz.lit.length; k++) room.pz['fire' + k].visible = false;
                    m.toast('The braziers gutter out. Try again — faster.');
                }
                if (room.r.hazard === 'fire' && !s.cleared) {
                    room.fireT = (room.fireT || 0) + dt;
                    const phase = room.fireT % 6;
                    const warn = phase > 3.3 && phase <= 4.5;
                    const active = phase > 4.5 && phase < 5.6;
                    if (room.fireGrates) for (const g of room.fireGrates) g.material.emissiveIntensity = active ? 1.5 : warn ? 0.55 + Math.sin(room.fireT * 18) * 0.35 : 0.12;
                    if (room.fireCones) for (const c of room.fireCones) { c.visible = active; if (active) c.scale.y = 0.82 + Math.sin(room.fireT * 26) * 0.22; }
                    if (active && inRoom && ((p.pos.z - room.z0) % 4) < 2) {
                        p.takeDamage(14 * dt * 3, null, true);
                        if (Math.random() < 0.25) BO.FX.spawnParticles(p.pos.clone(), 4, 0xff6a1a, 2, 3, 0.4);
                    }
                } else if (room.fireCones) {
                    for (const c of room.fireCones) c.visible = false;
                }
                if (room.boss && !room.boss.alive && room.boss.hp <= 0 && !s.boss) {
                    s.boss = true;
                    this.campaign.mark('dungeonBosses', 1, 300);
                    BO.ZoneThrill?.xp(250, 'Dungeon boss');
                    this.campaign.pack.dropBag({ medkits: 2, ammo9: 30, ammo556: 30, gold: 1 }, room.boss.pos);
                }
            }
            if (run.timed?.until && m.clock > run.timed.until && !run.timed.fired) {
                run.timed.fired = true;
                m.toast('LOCKDOWN. The vault floods with infected.');
                const last = run.rooms[run.rooms.length - 2] || run.rooms[0];
                this.spawnIn(run, last, 8, 1);
            }
        }

        /** HUD headline while inside. */
        status() {
            const run = this.inside;
            if (!run) return null;
            const m = this.mode;
            const left = run.rooms.reduce((a, r) => a + r.enemies.filter((z) => z.alive).length, 0);
            const t = run.timed?.until && !run.timed.fired ? ' · LOCKDOWN IN ' + Math.max(0, Math.ceil(run.timed.until - m.clock)) + ' S' : '';
            const pzRoom = run.rooms.find((r) => r.entered && !r.solved);
            return { headline: run.d.name + (left ? ' · ' + left + ' hostiles' : '') + t, sub: pzRoom ? 'Solve the puzzle to open the way' : 'Clear each room to open the next door' };
        }

        /* ------------------------------------------------------------ interaction */
        activate(mk) {
            if (!mk) return false;
            if (mk.dungeon) { this.enter(mk.dungeon); return true; }
            if (mk.dgnExit) { this.leave(); return true; }
            if (mk.dgnNote) { this.showNote(mk.name, mk.dgnNote); return true; }
            if (mk.puzzle) { this.puzzleAct(mk); return true; }
            if (mk.dgnChest) { this.openChest(mk); return true; }
            return false;
        }

        showNote(title, text) {
            BO.Events.emit('hud:banner', { title: title.toUpperCase(), sub: text, color: '#e8e0c8' });
            this.mode.toast(text);
        }

        openChest(mk) {
            const m = this.mode, run = this.inside;
            const tier = mk.dgnChest;
            const s = this.st(run.d.id);
            if (s.chest) return;
            s.chest = true;
            s.cleared = true;
            mk.alive = false;
            this.campaign.mark('dungeonsCleared', 1, 0);
            this.campaign.mark('dgn_clear_' + run.d.id, 1, 0);
            const a = BO.ZoneLoot.roll('military_crate', Math.min(4, tier));
            const b = BO.ZoneLoot.roll(tier >= 3 ? 'lab_cabinet' : 'toolbox', Math.min(4, tier));
            const items = { ...a.items };
            for (const [k, v] of Object.entries(b.items)) items[k] = (items[k] || 0) + v;
            items.medkits = (items.medkits || 0) + 1;
            if (tier >= 2) items.gold = (items.gold || 0) + tier - 1;
            m.grant(items);
            const pool = BO.ZoneLoot.WEAPON_POOLS[Math.min(4, tier)];
            const wid = pool[Math.floor(Math.random() * pool.length)];
            m.loot.offerWeapon(wid, Math.min(4, tier), BO.Player.pos, { floor: tier >= 4 ? 4 : tier >= 3 ? 3 : 2 });
            BO.ZoneThrill?.xp(80 + tier * 50, 'Dungeon cleared');
            BO.Sound?.playMysteryBoxJingle?.();
            BO.Events.emit('hud:banner', { title: 'DUNGEON CLEARED', sub: run.d.name.toUpperCase() + ' · THE PORTAL BESIDE THE CHEST LEADS HOME', color: '#ffb43a' });
        }

        leave(silent) {
            const run = this.inside;
            if (!run) return;
            const m = this.mode;
            for (const room of run.rooms) for (const z of room.enemies) if (z.alive) { z.alive = false; z.despawned = true; z.deathTimer = 0; if (z.parts?.root) z.parts.root.visible = false; }
            const pack = m.campaign?.pack;
            for (const depId of run.deposits || []) {
                const node = pack?.resources?.get(depId);
                if (!node) continue;
                for (const mesh of node.geometry || []) {
                    pack.meshToNode?.delete(mesh);
                    const wi = BO.World.worldMeshes?.indexOf(mesh) ?? -1;
                    if (wi >= 0) BO.World.worldMeshes.splice(wi, 1);
                    m.disposeOwned(mesh);
                }
                if (node.collider) {
                    node.collider.active = false;
                    BO.World.notifyColliderChanged?.(node.collider);
                    const ci = BO.World.colliders?.indexOf(node.collider) ?? -1;
                    if (ci >= 0) BO.World.colliders.splice(ci, 1);
                }
                if (node.marker) {
                    node.marker.alive = false;
                    const mi = m.markers.indexOf(node.marker);
                    if (mi >= 0) m.markers.splice(mi, 1);
                }
                pack.resources.delete(depId);
            }
            run.sp.dispose();
            this.light?.removeFromParent();
            this.inside = null;
            if (!silent && BO.Player.alive) {
                BO.Player.pos.set(run.ret.x, run.ret.y + 0.1, run.ret.z);
                BO.Player.vel.set(0, 0, 0);
                m.toast('Back in the open air.');
            }
            m.refreshTargets?.();
        }

        list() { return DUNGEONS.map((d) => ({ ...d, st: this.st(d.id), at: this.entrances.find((e) => e.d.id === d.id) })); }
    }

    // Sealed spaces sit far beyond the map: they belong to the region around their entrance (climate, discovery, enemy pools).
    if (BO.Zone?.regionAt && !BO.Zone._offMapRegion) {
        const regionAt = BO.Zone.regionAt;
        BO.Zone._offMapRegion = true;
        BO.Zone.regionAt = (x, z) => {
            if (Math.abs(x) < 1000) return regionAt(x, z);
            const r = BO.ZoneDungeons?.inside?.ret || BO.ZoneLegends?.arena?.ret || BO.Zone.HAVEN;
            return regionAt(r.x, r.z);
        };
    }
    BO.ZoneDungeons = new ZoneDungeons();
    BO.ZoneDungeons.DUNGEONS = DUNGEONS;
    BO.ZoneSpace = Space;
})(window.BO);
;

/* --- src/systems/ZoneLegends.js --- */
/* ============================================================================
   BLACKOUT OPS — The full roster, legendary hunts and the Pit Masters
   · Every infected type (70) now walks the Zone: the weakest first, harder
     ones joining the pool day by day (or all at once with a sandbox option).
   · Legendary hunts: twelve bosses that only appear after you meet their
     criteria (kills, hunting, cooking, mining, dungeons, vehicles…).
   · Pit Masters: NPCs who offer a boss duel. Say yes and you are taken to the
     arena; win and a portal home opens, with a reward chest and time to loot.
============================================================================ */
(function (BO) {
    'use strict';

    const LEGENDS = [
        { id: 'ravenous', name: 'The Ravenous', spec: 'boss_butcher', need: (c) => [c.metrics.kills || 0, 60], how: 'Kill 60 infected. The noise draws it.' },
        { id: 'lumberjack', name: 'The Lumberjack', spec: 'boss_butcher', need: (c) => [c.metrics.treesFelled || 0, 35], how: 'Fell 35 trees. It does not like what you are doing to its forest.' },
        { id: 'pyre', name: 'The Pyre Hound', spec: 'boss_cerberus', need: (c) => [c.metrics.meals || 0, 12], how: 'Cook 12 meals. It follows the smell of cooking.' },
        { id: 'matriarch', name: 'The Grand Matriarch', spec: 'boss_witch_queen', need: (c) => [c.metrics.puzzles || 0, 3], how: 'Solve 3 dungeon puzzles.' },
        { id: 'bride', name: 'The Night Bride', spec: 'boss_witch_queen', need: (c) => [c.metrics.nightKills || 0, 40], how: 'Kill 40 infected at night. Appears only at night.', night: true },
        { id: 'plague', name: 'Dr. Plague', spec: 'boss_plague', need: (c) => [c.metrics.secured || 0, 10], how: 'Secure 10 infested sites.' },
        { id: 'colossus', name: 'The Iron Colossus', spec: 'boss_colossus', need: (c) => [(c.metrics.vehiclesClaimed || 0) + (c.metrics.vehiclesBuilt || 0), 3], how: 'Claim or build 3 vehicles. It hunts engines.' },
        { id: 'apex', name: 'The Apex', spec: 'boss_manbearpig', need: (c) => [c.metrics.hunted || 0, 15], how: 'Hunt 15 animals. Something bigger hunts the hunter.' },
        { id: 'lycan', name: 'The Lycanthrope King', spec: 'boss_lycan_king', need: (c) => [c.metrics.hunt_wolf || 0, 6], how: 'Kill 6 wolves. Appears only at night.', night: true },
        { id: 'ogre', name: 'The Ogre Emperor', spec: 'boss_ogre_emperor', need: (c) => [c.metrics.oreHarvests || 0, 30], how: 'Mine 30 ore deposits.' },
        { id: 'hydra', name: 'The Hydra of the Deep', spec: 'boss_hydra_matron', need: (c) => [c.metrics.dungeonsCleared || 0, 3], how: 'Clear 3 dungeons.' },
        { id: 'nyx', name: 'Overlord Nyx', spec: 'boss_nyx', need: (c) => [c.metrics.legends || 0, 6], how: 'Defeat 6 other legendary bosses.' },
        { id: 'kronos', name: 'Kronos, Titan Colossus', spec: 'super_titan_colossus', need: (c) => [c.metrics.kills || 0, 110], how: 'Colossal Super Boss · Slay 110 infected in the Zone.' },
        { id: 'seraphim', name: 'Seraphim Nexus', spec: 'super_seraph_harbinger', need: (c) => [c.metrics.secured || 0, 6], how: 'Colossal Super Boss · Secure 6 infested or siege sites.' },
        { id: 'leviathan', name: 'Leviathan Hydra-Rex', spec: 'super_hydra_behemoth', need: (c) => [c.metrics.dungeonsCleared || 0, 2], how: 'Colossal Super Boss · Clear 2 Zone dungeons.' },
        { id: 'valkyr', name: 'Valkyr-09 Dreadnought', spec: 'super_dreadnought_mech', need: (c) => [c.metrics.pmc || 0, 12], how: 'Colossal Super Boss · Eliminate 12 PMC patrol soldiers.' },
        { id: 'malakor', name: 'Malakor, Eclipse Sovereign', spec: 'super_void_sovereign', need: (c) => [c.metrics.legends || 0, 8], how: 'Apex Super Boss · Defeat 8 Legendary Hunts. Appears at night.', night: true }
    ];

    const PIT_MASTERS = [
        { id: 'varga', name: 'Pit Master Varga', at: () => ({ x: BO.Zone.HAVEN.x + 6, z: BO.Zone.HAVEN.z - 4 }), line: '"Fancy yourself a fighter? I keep something in a cage for people like you."' },
        { id: 'oleg', name: 'Pit Master Oleg', poi: 'pharmacy', line: '"Ten bosses. One arena. Nobody has seen the tenth and lived."' },
        { id: 'mae', name: 'Pit Master Mae', poi: 'boathouse', line: '"You look bored. Let me fix that."' }
    ];

    const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

    class ZoneLegends {
        constructor() { this.state = {}; }
        get campaign() { return this.mode?.campaign; }

        /* ------------------------------------------------------------ install: full roster */
        static install() {
            if (ZoneLegends._installed) return;
            ZoneLegends._installed = true;
            const Z = BO.Zone;
            const ZD = BO.ZombiesData;
            Z.bestiary = () => ZD.ORDERED_PROGRESSION.filter(Boolean);
            const C = BO.SurvivalCampaign.prototype;
            const KEY = {
                crash: 'shambler|ankle_biter', relay: 'shambler|ankle_biter|sprinter', hollow: 'shambler|hunch_spitter|one_arm_ripper',
                kessel: 'shield|juggernaut|goliath|charger', pine: 'stalker|sprinter|ripper|wolf|lycan', spillway: 'waddler|bloater|spitter|drown|swamp',
                frost: 'goliath|frost|ice|yeti|charger', cinder: 'bloater|charger|juggernaut|fire|ember|lava', campus: 'stalker|shield|juggernaut|lab|mutant', crater: 'juggernaut|goliath|stalker|void'
            };
            C.getPool = function (area) {
                const all = this.roster;
                const day = this.mode.threat?.day || this.day;
                const tierBoost = Math.max(0, (BO.Zone.REGIONS.find((r) => r.id === area)?.threat || 1) - 1);
                const n = this.has('sv_all_enemies') ? all.length : Math.min(all.length, 8 + (day - 1) * 6 + tierBoost * 3);
                const defaultAllowed = new Set(all.slice(0, Math.max(1, n)).map((z) => z.id));
                const ZC = BO.ZombieCustomizer;
                const filtered = all.filter((z) => {
                    if (ZC) {
                        const customStart = ZC.getStartRound(z.id);
                        if (customStart != null) return day >= customStart;
                    }
                    return defaultAllowed.has(z.id);
                });
                const allowed = filtered.length ? filtered : all.slice(0, 1);
                const kw = KEY[area] ? new RegExp(KEY[area], 'i') : null;
                const preferred = kw ? allowed.filter((z) => kw.test(z.id) || kw.test(z.name || '')) : [];
                // Region favourites are doubled; the newest unlocks are always in the mix.
                return [...allowed, ...preferred, ...allowed.slice(-4)];
            };
            const canSave = C.canSave;
            C.canSave = function () { return canSave.call(this) && !BO.ZoneDungeons?.inside && !BO.ZoneLegends?.arena; };
        }

        start(mode, saved) {
            ZoneLegends.install();
            this.stop();
            this.mode = mode;
            this.state = JSON.parse(JSON.stringify(saved?.state || {}));
            this.ladder = saved?.ladder || 0;
            this.lastDay = mode.campaign.day;
            this.unlockedSeen = this.unlockedCount();
            this.objects = [];
            this.arena = null;
            this.dialog = null;
            this.legendClock = 6;
            if (!mode.campaign.has('sv_no_npcs')) for (const pm of PIT_MASTERS) this.placeNpc(pm);
        }

        stop() {
            if (this.arena) this.leaveArena(true);
            this.closeDialog(true);
            for (const o of this.objects || []) o.removeFromParent?.();
            this.objects = [];
            for (const L of LEGENDS) { const e = this.state[L.id]?.entity; if (e?.alive) { e.alive = false; e.despawned = true; e.deathTimer = 0; if (e.parts?.root) e.parts.root.visible = false; } }
            this.mode = null;
        }

        snapshot() {
            const st = {};
            for (const [k, v] of Object.entries(this.state)) st[k] = { s: v.s === 'spawned' ? 'met' : v.s };
            return { state: st, ladder: this.ladder };
        }

        unlockedCount() {
            const c = this.campaign;
            return c ? c.getPool(c.area?.id || 'crash').filter((v, i, a) => a.indexOf(v) === i).length : 0;
        }

        /* ------------------------------------------------------------ legendary hunts */
        legendStatus() {
            const c = this.campaign;
            return LEGENDS.map((L) => {
                let cur = 0, need = 1;
                try { [cur, need] = L.need(c); } catch (_) { /* metric missing */ }
                return { ...L, cur: Math.min(cur, need), need, s: this.state[L.id]?.s || 'locked' };
            });
        }

        updateLegends(dt) {
            const m = this.mode, c = this.campaign;
            this.legendClock -= dt;
            if (this.legendClock > 0) return;
            this.legendClock = 3;
            if (!m.hostilesReleased || BO.ZoneDungeons?.inside || this.arena || BO.ZoneFinale?.active || !BO.Player.alive) return;
            for (const L of this.legendStatus()) {
                const st = this.state[L.id] || (this.state[L.id] = { s: 'locked' });
                if (st.s === 'dead') continue;
                if (st.s === 'locked' && L.cur >= L.need) {
                    st.s = 'met';
                    st.at = m.clock + 20;
                    BO.Events.emit('hud:banner', { title: 'LEGENDARY HUNT', sub: L.name.toUpperCase() + ' HAS TAKEN NOTICE OF YOU', color: '#ff6b5b' });
                    BO.Sound?.playBossIntro?.();
                }
                if (st.s === 'met' && m.clock >= (st.at || 0) && (!L.night || c.isNight)) this.spawnLegend(L, st);
                if (st.s === 'spawned') {
                    const e = st.entity;
                    if (!e || e.despawned) { st.s = 'met'; st.at = m.clock + 60; }
                    else if (!e.alive && e.hp <= 0) this.legendDown(L, st);
                }
            }
        }

        spawnLegend(L, st) {
            const m = this.mode;
            const p = BO.Player.pos;
            const nav = BO.World.nav;
            let spot = null;
            for (let t = 0; t < 20 && !spot; t++) {
                const a = Math.random() * Math.PI * 2, d = 30 + Math.random() * 20;
                const x = p.x + Math.cos(a) * d, z = p.z + Math.sin(a) * d;
                const j = nav?.idx(x, z) ?? -1;
                if (j >= 0 && nav.walk[j]) spot = { x, z, y: nav.y[j] };
            }
            if (!spot) return;
            const idx = LEGENDS.indexOf(L);
            const zb = m.spawnInfected(spot.x, BO.World.getGroundHeight(spot.x, spot.z, spot.y + 2), spot.z, 'normal', L.spec, true);
            if (!zb) return;
            zb.legend = L.id;
            zb.bossLabel = L.name;
            zb.maxHp = zb.hp = Math.round((1300 + idx * 320) * (m.tierSpec?.hp || 1) * (m.difficultyRules?.hp || 1));
            zb.damage = Math.round((28 + idx * 3) * (m.difficultyRules?.damage || 1));
            zb.speed = 2.9;
            zb.zs = { state: 'hunt', home: { x: spot.x, z: spot.z }, x: spot.x, z: spot.z, until: 0, seen: m.clock, wander: 0 };
            st.s = 'spawned';
            st.entity = zb;
            m.refreshTargets();
            BO.Events.emit('hud:banner', { title: L.name.toUpperCase(), sub: 'LEGENDARY BOSS · IT IS COMING FOR YOU', color: '#ff6b5b' });
        }

        legendDown(L, st) {
            const m = this.mode;
            st.s = 'dead';
            const pos = st.entity.pos.clone();
            st.entity = null;
            m.campaign.mark('legends', 1, 0);
            BO.ZoneThrill?.xp(400, 'Legend slain');
            m.campaign.pack.dropBag({ medkits: 3, gold: 2, ammo556: 40, ammo762: 30, relic: 1 }, pos);
            const pool = BO.ZoneLoot.WEAPON_POOLS[4];
            const wid = pool[Math.floor(Math.random() * pool.length)];
            m.loot.dropPickup(wid, 100, pos, BO.WeaponsData.get(wid)?.name, BO.ZoneThrill?.rollWeapon(wid, 4, 4) || null);
            BO.Events.emit('hud:banner', { title: 'LEGEND SLAIN', sub: L.name.toUpperCase() + ' · LEGENDARY WEAPON DROPPED', color: '#ffb43a' });
        }

        /* ------------------------------------------------------------ roster unlock news */
        updateRoster() {
            const c = this.campaign;
            if (c.day === this.lastDay) return;
            this.lastDay = c.day;
            const n = this.unlockedCount();
            if (n > this.unlockedSeen) {
                const fresh = c.roster.slice(this.unlockedSeen, n).map((z) => z.name).slice(0, 4);
                this.mode.toast('New infected now roam the Zone: ' + fresh.join(', ') + (n - this.unlockedSeen > 4 ? ' and ' + (n - this.unlockedSeen - 4) + ' more' : '') + '.');
                this.unlockedSeen = n;
            }
        }

        /* ------------------------------------------------------------ Pit Masters */
        placeNpc(pm) {
            const m = this.mode;
            let at = pm.at?.();
            if (!at) { const poi = BO.Zone.pois.find((p) => p.type === pm.poi); if (!poi) return; at = { x: poi.x + poi.w / 2 + 2, z: poi.z + poi.d / 2 + 2 }; }
            const y = BO.World.getGroundHeight(at.x, at.z, BO.World.terrainHeight(at.x, at.z) + 2);
            const g = new THREE.Group();
            const mat = (c) => new THREE.MeshStandardMaterial({ color: new THREE.Color(c).convertSRGBToLinear(), roughness: 0.8 });
            const add = (w, h, d, c, x, yy, z) => { const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(c)); mesh.position.set(x, yy, z); mesh.castShadow = true; g.add(mesh); return mesh; };
            add(0.5, 0.75, 0.3, 0x3a3228, 0, 1.15, 0); add(0.3, 0.3, 0.3, 0xd8b090, 0, 1.72, 0); add(0.55, 0.1, 0.32, 0xb02a2a, 0, 1.48, 0);
            add(0.18, 0.8, 0.2, 0x2a2a2a, -0.12, 0.4, 0); add(0.18, 0.8, 0.2, 0x2a2a2a, 0.12, 0.4, 0);
            add(0.12, 0.7, 0.12, 0x3a3228, -0.33, 1.1, 0); add(0.12, 0.7, 0.12, 0x3a3228, 0.33, 1.1, 0);
            const sign = add(0.5, 0.5, 0.05, 0xffb43a, 0, 2.45, 0);
            sign.material.emissive = new THREE.Color(0xff8a20); sign.material.emissiveIntensity = 1;
            g.position.set(at.x, y, at.z);
            m.scene.add(g);
            this.objects.push(g);
            m.markers.push({ id: 'pit:' + pm.id, x: at.x, y, z: at.z, name: pm.name, label: 'Talk to ' + pm.name + ' (boss duels)', alive: true, pit: pm, reach: 2.6 });
        }

        bosses() {
            return BO.ZombiesData.ORDERED_BOSSES.map((b, i) => ({ id: b.id, name: b.name.replace(/\b\w+/g, (w) => w[0] + w.slice(1).toLowerCase()), rank: i, hp: Math.round((1500 + i * 650) * (this.mode.tierSpec?.hp || 1)), beaten: i < this.ladder, open: i <= this.ladder || this.campaign.has('sv_all_unlocks') }));
        }

        openDialog(pm, confirm = null) {
            this.dialog = { pm, confirm };
            if (document.pointerLockElement) document.exitPointerLock();
            if (!this.dlgEl) {
                this.dlgEl = document.createElement('div');
                this.dlgEl.className = 'zt-box zt-dlg';
                document.body.appendChild(this.dlgEl);
                this.dlgEl.addEventListener('click', (e) => this.dialogClick(e));
            }
            const list = this.bosses();
            const b = confirm !== null ? list[confirm] : null;
            this.dlgEl.innerHTML = b ? `<div class="zt-box-in zt-confirm"><header><b>${esc(pm.name)}</b></header>
                    <p class="zt-line">"So — <b>${esc(b.name)}</b>. ${b.hp} health and a temper. You sure?"</p>
                    <p class="sv-muted">You will be taken to the arena. Win and a portal home opens, with a reward chest and 90 seconds to loot. Use the portal early to forfeit.</p>
                    <div class="zt-yesno"><button data-dlg-yes="${confirm}">Yes — take me to the arena</button><button data-dlg-no>No, not yet</button></div></div>`
                : `<div class="zt-box-in"><header><b>${esc(pm.name)}</b><span>${esc(pm.line)}</span><button data-dlg-close>Leave · Esc</button></header>
                    <div class="zt-ladder">${list.map((x) => `<button data-dlg-pick="${x.rank}" ${x.open ? '' : 'disabled'} class="${x.beaten ? 'beaten' : ''}"><em>${x.rank + 1}</em><b>${esc(x.name)}</b><small>${x.beaten ? 'Beaten · fight again' : x.open ? x.hp + ' HP · reward: Epic+ weapon' : 'Beat the previous boss first'}</small></button>`).join('')}</div></div>`;
        }

        dialogClick(e) {
            const t = e.target.closest('button');
            if (!t || !this.dialog) return;
            const d = t.dataset;
            if (d.dlgClose !== undefined) return this.closeDialog();
            if (d.dlgNo !== undefined) return this.openDialog(this.dialog.pm);
            if (d.dlgPick !== undefined) return this.openDialog(this.dialog.pm, +d.dlgPick);
            if (d.dlgYes !== undefined) { const rank = +d.dlgYes; this.closeDialog(true); this.enterArena(rank); BO.App?._safePointerLock?.(); }
        }

        closeDialog(silent) {
            if (!this.dialog) return;
            this.dialog = null;
            this.dlgEl?.remove();
            this.dlgEl = null;
            if (!silent && BO.State.screen === 'playing') BO.App?._safePointerLock?.();
        }

        handleKey(e) {
            if (!this.dialog) return false;
            if (e.code === 'Escape') { e.preventDefault(); this.closeDialog(); }
            return true;
        }

        /* ------------------------------------------------------------ the arena */
        enterArena(rank) {
            const m = this.mode;
            if (this.arena || BO.ZoneDungeons?.inside) return;
            const b = this.bosses()[rank];
            const ox = 6000, oz = 0, R = 22, H = 7;
            const sp = new BO.ZoneSpace(m, ox, oz, 0x6a5a4a);
            sp.box(ox, -0.25, oz, R * 2 + 1, 0.5, R * 2 + 1, 0x7a6a52);
            for (const [x, z, w, d] of [[ox - R, oz, 0.6, R * 2], [ox + R, oz, 0.6, R * 2], [ox, oz - R, R * 2, 0.6], [ox, oz + R, R * 2, 0.6]]) sp.box(x, H / 2, z, w, H, d, 0x5a4a3a);
            for (let i = 0; i < 8; i++) {
                const a = i / 8 * Math.PI * 2;
                const x = ox + Math.cos(a) * (R - 5), z = oz + Math.sin(a) * (R - 5);
                sp.box(x, 2.5, z, 1.4, 5, 1.4, 0x8a7a62);
                sp.box(x, 5.3, z, 0.6, 0.6, 0.6, 0xff8a20, false, { emissive: new THREE.Color(0xff7a10), emissiveIntensity: 1.6 });
            }
            const p = BO.Player;
            const wait = m.campaign.has('sv_no_cooldowns') ? 0.3 : 3;
            this.arena = { rank, b, sp, ret: { x: p.pos.x, y: p.pos.y, z: p.pos.z }, start: m.clock + wait, boss: null, won: false, portalAt: 0 };
            this.light = this.light || new THREE.PointLight(0xffc890, 1.2, 40, 1.4);
            this.light.position.set(ox, 9, oz);
            m.scene.add(this.light);
            p.pos.set(ox, 0.1, oz - R + 3);
            p.vel.set(0, 0, 0);
            p.yaw = Math.PI;
            BO.Events.emit('hud:banner', { title: 'THE ARENA', sub: b.name.toUpperCase() + ' · FIGHT BEGINS IN 3', color: '#ff6b5b' });
            m.campaign.mark('arenaFights', 1, 0);
        }

        updateArena(dt) {
            const A = this.arena, m = this.mode;
            if (!A) return;
            A.sp.tick?.(dt, m.clock);
            const p = BO.Player;
            if (!p.alive) return;
            if (Math.abs(p.pos.x - A.sp.ox) > 60) { this.leaveArena(true); return; }
            if (p.pos.y < -20) { p.pos.set(A.sp.ox, 0.2, A.sp.oz); p.vel.set(0, 0, 0); }
            if (!A.boss && !A.won && m.clock >= A.start) {
                const zb = m.spawnInfected(A.sp.ox, 0.05, A.sp.oz + 14, 'normal', A.b.id, true);
                if (zb) {
                    zb.arena = true;
                    zb.bossLabel = A.b.name;
                    zb.maxHp = zb.hp = Math.round(A.b.hp * (m.difficultyRules?.hp || 1));
                    zb.damage = Math.round((28 + A.rank * 5) * (m.difficultyRules?.damage || 1));
                    zb.speed = 2.6 + A.rank * 0.08;
                    zb.zs = { state: 'hunt', home: { x: A.sp.ox, z: A.sp.oz }, x: A.sp.ox, z: A.sp.oz, until: 0, seen: m.clock, wander: 0 };
                    A.boss = zb;
                    m.refreshTargets();
                    BO.Sound?.playBossIntro?.();
                    BO.Events.emit('hud:banner', { title: 'FIGHT!', sub: A.b.name.toUpperCase(), color: '#ff6b5b' });
                }
            }
            if (A.boss && !A.won && !A.boss.alive && A.boss.hp <= 0) {
                A.won = true;
                A.portalAt = m.clock + 90;
                if (A.rank >= this.ladder) this.ladder = A.rank + 1;
                m.campaign.mark('arenaWins', 1, 0);
                BO.ZoneThrill?.xp(200 + A.rank * 60, 'Arena victory');
                const sp = A.sp;
                const ring = new THREE.Mesh(new THREE.TorusGeometry(1.3, 0.15, 8, 28), new THREE.MeshBasicMaterial({ color: new THREE.Color(0x8fe3c8).convertSRGBToLinear() }));
                ring.position.set(sp.ox, 1.6, sp.oz);
                m.scene.add(ring); sp.meshes.push(ring); sp.portals?.push(ring);
                sp.marker({ id: 'arenaportal', x: sp.ox, y: 0, z: sp.oz, name: 'Portal home', label: 'Step through the portal home', arenaExit: true, reach: 2.2 });
                sp.box(sp.ox + 4, 0.45, sp.oz, 1.5, 0.9, 1, 0x8a6a2a, true, { emissive: new THREE.Color(0xffb43a), emissiveIntensity: 0.4 });
                sp.marker({ id: 'arenachest', x: sp.ox + 4, y: 0, z: sp.oz - 1, name: 'Arena reward chest', label: 'Open the reward chest', arenaChest: true, reach: 2.2 });
                BO.Events.emit('hud:banner', { title: 'VICTORY', sub: A.b.name.toUpperCase() + ' DEFEATED · PORTAL HOME OPEN FOR 90 S', color: '#ffb43a' });
            }
            if (A.won && m.clock > A.portalAt) this.leaveArena();
        }

        arenaChest(mk) {
            const A = this.arena, m = this.mode;
            mk.alive = false;
            const tier = Math.min(4, 2 + Math.floor(A.rank / 3));
            const a = BO.ZoneLoot.roll('military_crate', tier);
            m.grant({ ...a.items, medkits: 2, gold: 1 + Math.floor(A.rank / 2) });
            const pool = BO.ZoneLoot.WEAPON_POOLS[tier];
            const wid = pool[Math.floor(Math.random() * pool.length)];
            m.loot.offerWeapon(wid, tier, BO.Player.pos, { floor: A.rank >= 6 ? 4 : 3 });
            if (BO.ZoneThrill) BO.ZoneThrill.rerolls++;
            BO.Sound?.playMysteryBoxJingle?.();
        }

        leaveArena(silent) {
            const A = this.arena;
            if (!A) return;
            if (A.boss?.alive) { A.boss.alive = false; A.boss.despawned = true; A.boss.deathTimer = 0; if (A.boss.parts?.root) A.boss.parts.root.visible = false; }
            A.sp.dispose();
            this.light?.removeFromParent();
            this.arena = null;
            if (!silent && BO.Player.alive) { BO.Player.pos.set(A.ret.x, A.ret.y + 0.2, A.ret.z); BO.Player.vel.set(0, 0, 0); this.mode.toast(A.won ? 'You step back into the Zone, victorious.' : 'You forfeit the duel.'); }
            this.mode.refreshTargets?.();
        }

        status() {
            const A = this.arena, m = this.mode;
            if (!A) return null;
            if (A.won) return { headline: 'Victory · portal home closes in ' + Math.max(0, Math.ceil(A.portalAt - m.clock)) + ' s', sub: 'Open the reward chest, loot the boss, then step through the portal' };
            if (!A.boss) return { headline: 'The arena · ' + A.b.name, sub: 'Get ready…' };
            return { headline: A.b.name + ' · ' + Math.ceil(A.boss.hp) + ' HP', sub: 'Arena duel · the portal opens when it falls' };
        }

        activate(mk) {
            if (mk?.pit) { this.openDialog(mk.pit); return true; }
            if (mk?.arenaExit) { this.leaveArena(); return true; }
            if (mk?.arenaChest) { this.arenaChest(mk); return true; }
            return false;
        }

        update(dt) {
            if (!this.mode?.active) return;
            this.updateRoster();
            this.updateLegends(dt);
            this.updateArena(dt);
        }
    }

    ZoneLegends.install();
    BO.ZoneLegends = new ZoneLegends();
    BO.ZoneLegends.LEGENDS = LEGENDS;
    BO.ZoneLegendsClass = ZoneLegends;
})(window.BO);
;

